  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Monter la vinaigrette en premier pour qu''elle attende au frais : délayer la moutarde de Dijon dans le vinaigre de vin rouge avec le sel fin, puis incorporer 90 g d''huile d''olive en mince filet au fouet jusqu''à ce que le mélange épaississe et cesse de se séparer. Poivrer et réserver ; les 30 g d''huile restants serviront au pain.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Poser les lardons fumés dans une poêle froide sans aucune matière grasse, monter à feu moyen et les laisser rendre leur gras puis colorer une petite dizaine de minutes en remuant de temps en temps. Les débarrasser sur du papier absorbant et jeter la graisse de la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Compter environ 130 g de noix en coquille chez le primeur pour obtenir les 55 g de cerneaux utiles ici — la coque part à la poubelle et représente plus de la moitié du poids acheté. Casser, trier, puis concasser les cerneaux au couteau en gros éclats irréguliers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Mettre le gril du four en chauffe à 220 °C avec une plaque garnie de papier cuisson. Trancher le pain de campagne en quatre larges tranches d''environ 50 g et un doigt d''épaisseur, puis les badigeonner d''huile d''olive sur la face qui recevra le fromage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ôter les deux extrémités croûtées de la bûche de chèvre et la débiter en quatre rondelles d''environ 25 g. En coiffer chaque tranche de pain, déposer un filet de miel sur le fromage et pincer les herbes de Provence entre les doigts au-dessus des toasts pour les réveiller.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Glisser la plaque sous le gril à mi-hauteur et surveiller sans s''éloigner : cinq à huit minutes suffisent pour que le chèvre s''affaisse, blondisse par endroits et laisse apparaître de petites bulles en surface. Le pain doit rester ferme dessous, jamais desséché.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Pendant le gratinage, laver et essorer la laitue, la répartir en dômes dans quatre assiettes, semer la tomate râpée, les lardons égouttés et les éclats de noix. Napper de vinaigrette au dernier moment, puis poser un toast brûlant sur chaque assiette et servir sans attendre pour garder le contraste chaud-froid.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-053', 'recipe_family', 'Salade de chèvre chaud',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-053', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Chèvre pané : tremper les rondelles dans l''œuf cru puis dans la chapelure de blé et les dorer à la poêle au lieu de les gratiner sur le pain','Remplacer la tomate râpée par des tomates cerises coupées en deux, comme le font la moitié des sources','Version sans porc : troquer les lardons contre des pignons de pin grillés à sec dans une poêle chaude','Ajouter de fines lamelles de poire ou quelques feuilles de basilic frais pour une note sucrée et parfumée']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-053","variants":["Chèvre pané : tremper les rondelles dans l''œuf cru puis dans la chapelure de blé et les dorer à la poêle au lieu de les gratiner sur le pain","Remplacer la tomate râpée par des tomates cerises coupées en deux, comme le font la moitié des sources","Version sans porc : troquer les lardons contre des pignons de pin grillés à sec dans une poêle chaude","Ajouter de fines lamelles de poire ou quelques feuilles de basilic frais pour une note sucrée et parfumée"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-053', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('883b8c481a89114b916da2d81e9cb3e8'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3},"dominant_flavors":["chèvre lactique","acidité vinaigrée","miel","fumé"],"aroma_families":["lactée","herbacée","toastée"],"target_textures":["fromage fondant","pain croustillant","feuilles croquantes","éclats de noix"],"signature_ingredients":["Fromage de chèvre bûche","Pain de campagne","Miel"],"identity_guardrails":["Le chèvre doit arriver chaud et coulant sur l''assiette : servi froid ou émietté à cru, le plat perd son nom","Le pain de campagne grillé sous le fromage est le socle du plat, pas une garniture — sans lui il ne reste qu''une salade au fromage","La vinaigrette reste franchement acidulée pour trancher la richesse du fromage et du gras des lardons"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade landaise', 'salade landaise', 'France', 'France',
     'meal', 'salade composée', 'named_traditional_dish', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Salade landaise', 'Salade avec confit de canard chaud, tomates et vinaigrette moutardée', ds.id, 'SRC-054',
    'Myko', 'editorial', 4, 15, 10, 'facile',
    NULL, NULL,
    'B', 'candidate', 'c04bbf579b0c8b867b41a0a8bfecdb9e',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3}'::jsonb, ARRAY['gras de canard confit','acidité vinaigrée','moutarde']::text[],
    ARRAY['rôti','végétal frais','acidulé']::text[], ARRAY['peau de canard croustillante','chair effilochée fondante','pulpe de tomate fraîche']::text[],
    ARRAY['Confit de canard cuit','Moutarde de Dijon','Huile d''olive vierge extra']::text[], ARRAY['Sans canard confit, ce n''est plus une salade landaise : le gras de canard tiédi est le cœur du plat, aucune autre viande ne le remplace.','La sauce doit rester une vinaigrette moutardée et franchement acide, seule capable de trancher le gras ; une sauce crémée efface l''identité gasconne.','Le canard se pose tiède sur une base froide et non assaisonnée à l''avance : tout réchauffer ou tout laisser refroidir transforme le plat en autre chose.']::text[],
    ARRAY['saisie','émulsion']::text[], ARRAY['Monter l''assiette sur un lit de frisée ou de jeunes pousses assaisonnées, comme le fait la majorité des pages du dossier.','Ajouter des gésiers confits réchauffés à la poêle, taillés en morceaux, et deux tranches de magret fumé par personne.','Version festive : une tranche de foie gras de canard posée au centre juste avant de servir.','Variante landaise à la truite fumée, détaillée en lanières, en remplacement d''une partie du canard.','Parsemer de pignons torréfiés à sec et glisser une échalote ciselée dans la vinaigrette.']::text[], ARRAY['moutarde','sulfites']::text[],
    'À manger dans la foulée du dressage. Les éléments se gardent séparément : chair de canard désossée trois jours à 4 °C recouverte de sa graisse, vinaigrette une semaine au réfrigérateur en bocal fermé, pulpe de tomate le jour même. Une fois assaisonnée, la salade s''affaisse en moins d''une heure. Ne se congèle pas : la tomate râpée rend toute son eau à la décongélation et la peau croustillante devient molle ; seul le confit non désossé supporte le congélateur, trois mois sous graisse.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
