     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'optional',
     'assaisonnement', true, 9);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir chez le poissonnier un tronçon de saumon d''environ 800 g avec sa peau : une fois la peau détachée au couteau souple et les arêtes retirées à la pince, il reste les 600 g de chair nette de la liste, à recouper en quatre pavés réguliers de 150 g. Les garder au frais, à plat sur une assiette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Compter à peu près 300 g d''oseille en bottes pour obtenir les 200 g de feuilles nettes : effeuiller, ôter la côte centrale en tirant la nervure de la base vers la pointe, laver à grande eau, essorer sans écraser puis tailler grossièrement en larges lanières.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Peler et hacher menu les échalotes. Les laisser suer dans le beurre à feu doux, en sauteuse large, jusqu''à ce qu''elles perdent leur mordant et deviennent translucides sans prendre la moindre couleur, environ trois minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Mouiller au vin blanc, remonter le feu et conduire la réduction jusqu''au sirop, presque à sec, le temps que l''odeur d''alcool s''efface complètement du dessus de la sauteuse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter la crème, ramener à petits frémissements et laisser épaissir quelques minutes, jusqu''à ce qu''un trait tracé au doigt tienne au dos de la cuillère. Rectifier en sel et en poivre à ce stade, la sauce ne se resalera plus ensuite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Jeter les lanières d''oseille dans la crème chaude, feu coupé ou très doux : elles s''affaissent et virent au vert olive en moins d''une minute. Arrêter là et réserver à couvert sans bouillir — une cuisson prolongée brunit l''oseille et efface l''acidité qui fait tout le plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Chauffer l''huile d''olive dans une poêle jusqu''à ce qu''elle ondule. Assaisonner les pavés sur les deux faces, les poser sans les serrer et les saisir environ trois minutes sur la première face, deux sur la seconde : le cœur doit rester légèrement translucide et se détacher en larges feuillets.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Dresser les pavés dans des assiettes chaudes, les napper de sauce à l''oseille au tout dernier moment et servir aussitôt, avec des pommes de terre vapeur ou de larges pâtes fraîches.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-055', 'recipe_family', 'Saumon à l''oseille',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-055', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version Troisgros : aplatir les escalopes de saumon très finement entre deux feuilles, ne les saisir que vingt-cinq secondes sur une seule face et monter la sauce sur un fumet de poisson réduit.','Remplacer le vin blanc sec par la même quantité de vermouth sec, comme le fait l''une des sources du dossier.','Servir la sauce et le saumon effeuillé sur de larges pâtes fraîches, en parsemant au dressage quelques lanières d''oseille crue pour relancer l''acidité.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-055","variants":["Version Troisgros : aplatir les escalopes de saumon très finement entre deux feuilles, ne les saisir que vingt-cinq secondes sur une seule face et monter la sauce sur un fumet de poisson réduit.","Remplacer le vin blanc sec par la même quantité de vermouth sec, comme le fait l''une des sources du dossier.","Servir la sauce et le saumon effeuillé sur de larges pâtes fraîches, en parsemant au dressage quelques lanières d''oseille crue pour relancer l''acidité."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-055', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('5cd5a59983c84f5e24e69624456d270d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":5,"freshness":3,"intensity":3},"dominant_flavors":["acidulé végétal","lacté beurré","gras iodé du saumon"],"aroma_families":["lactée","végétale acidulée","marine"],"target_textures":["chair nacrée qui se détache en feuillets","sauce nappante","oseille fondue"],"signature_ingredients":["Pavé de saumon cru, sans peau","Oseille crue","Crème fraîche liquide entière"],"identity_guardrails":["Sans oseille fondue dans la crème, ce n''est plus un saumon à l''oseille : c''est son acidité citronnée qui coupe le gras du poisson et de la crème, aucun jus de citron ne la remplace.","Le saumon est saisi à part et nappé au dernier moment, jamais cuit dans la sauce : pochée dedans, la chair grise, se dessèche et perd le nacré qui fait le plat.","La liaison se fait à la crème réduite, sans farine ni roux — une sauce épaissie à la farine transforme le plat en gratin de poisson."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Soufflé au fromage', 'souffle au fromage', 'France', 'France',
     'meal', 'plat au four', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Soufflé au fromage', 'Appareil de béchamel au gruyère et emmental allégé avec des blancs montés, cuit aussitôt au four', ds.id, 'SRC-056',
    'Myko', 'editorial', 4, 20, 35, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'ad8cc13d3b8fa54788417130362746ce',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['fromage affiné','beurre','jaune d''œuf']::text[],
    ARRAY['lactée','beurrée','épicée douce']::text[], ARRAY['mousseux','aérien','croûte dorée','cœur crémeux']::text[],
    ARRAY['Œuf cru','Gruyère râpé','Emmental râpé']::text[], ARRAY['Les blancs doivent être montés à part et incorporés à la maryse en fin d''appareil : mélangés au batteur ou battus avec les jaunes, la préparation ne lève plus et devient une omelette au four.','Le fromage à pâte pressée cuite râpé, emmental et gruyère, porte tout le goût du plat : sans lui il ne reste qu''un soufflé nature.','La base doit être une béchamel épaisse au beurre et à la farine, seule assez ferme pour tenir les bulles d''air ; un liant à la fécule délayée donne une texture caoutchouteuse hors identité.','Le moule se remplit aux deux tiers au maximum et la porte du four reste fermée en début de cuisson, sinon la levée s''effondre.']::text[],
    ARRAY['béchamel','blancs en neige','cuisson au four']::text[], ARRAY['Soufflés individuels : répartir l''appareil dans six ramequins beurrés et chemisés de gruyère, cuisson ramenée à 18-20 minutes.','Fromage plus typé : remplacer tout ou partie de l''emmental par un comté vieux, ou ajouter une soixantaine de grammes de mimolette vieille comme le fait l''une des sources du dossier.','Version express sans roux relevée dans le corpus : œufs battus en omelette avec fromage blanc, fécule et fromage râpé, versés dans un moule huilé — plus dense, plus rustique, et sans véritable levée.','Soufflé aux herbes : une cuillerée de ciboulette ou d''estragon ciselé ajoutée aux jaunes, sans jamais dépasser cette dose sous peine d''alourdir l''appareil.']::text[], ARRAY['lait','œuf','gluten']::text[],
    'Un soufflé se mange dans la minute où il sort du four : il commence à retomber en deux à trois minutes et ne se rattrape pas. Les restes se gardent couverts 48 heures au réfrigérateur à 4 °C et se réchauffent 10 minutes à 150 °C, en acceptant qu''ils restent plats et se rapprochent d''un flan au fromage. L''appareil cru ne se garde pas et ne s''anticipe pas, les blancs retombant en une quinzaine de minutes. La congélation est à proscrire, avant comme après cuisson : elle détruit la mousse et fait rendre son eau à la béchamel.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oeuf cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Œuf cru', 200, 'g', 'required',
     'protéine', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'lait entier' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Lait entier', 275, 'ml', 'required',
     'liquide', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'beurre doux' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Beurre doux', 50, 'g', 'required',
     'matière grasse', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'farine de ble t55' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Farine de blé T55', 50, 'g', 'required',
     'liant', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'emmental rape' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Emmental râpé', 105, 'g', 'required',
     'fromage', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'gruyere rape' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Gruyère râpé', 70, 'g', 'required',
     'fromage', false, 6);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'muscade moulue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Muscade moulue', 0.4, 'g', 'optional',
     'aromate', true, 7);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 4, 'g', 'optional',
     'assaisonnement', true, 8);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'optional',
     'assaisonnement', true, 9);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Sortir les œufs du froid une heure avant de commencer : des blancs à température ambiante prennent du volume plus vite et plus haut. Chauffer le four à 180 °C en chaleur tournante, grille placée au tiers bas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Prélever une noix sur les 50 g de beurre doux et en enduire au pinceau un moule à soufflé haut d''environ 18 cm, en montant du fond vers le haut par traits verticaux. Saupoudrer les parois beurrées d''une cuillerée prise sur le gruyère râpé, puis retourner le moule pour chasser l''excédent : cette paroi rugueuse donne prise à l''appareil qui grimpe.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Compter quatre œufs moyens, soit près de 240 g sur la balance coquille comprise, pour les 200 g de matière utile de la recette. Les casser en séparant les blancs dans un grand saladier bien sec et les jaunes dans un bol.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire fondre le beurre restant à feu doux dans une casserole à fond épais, y verser la farine de blé T55 en pluie et travailler au fouet une bonne minute : le mélange doit gonfler légèrement et sentir le biscuit sec, sans jamais prendre de couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser d''un seul coup le lait entier préalablement tiédi sur ce roux, monter le feu et fouetter sans interruption. La sauce s''épaissit en deux ou trois minutes et nappe franchement le fouet dès les premiers bouillons : retirer aussitôt du feu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Laisser retomber la chaleur cinq minutes, puis incorporer les jaunes un par un au fouet, en attendant que chacun disparaisse avant d''ajouter le suivant. Verser ensuite l''emmental râpé et le gruyère râpé restant en plusieurs fois, hors du feu, jusqu''à obtenir une base lisse et brillante. Râper la muscade moulue, poivrer, et saler d''une main légère seulement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Monter les blancs avec une pincée prise sur le sel fin, d''abord à vitesse moyenne puis en accélérant, jusqu''à ce qu''ils tiennent au fouet en formant une pointe qui s''incline à peine.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Détendre la base encore tiède avec un gros tiers des blancs travaillé sans ménagement, ce qui l''allège et la rend réceptive. Ajouter le reste en deux fois, à la maryse, en coupant la masse verticalement puis en la ramenant par-dessous en tournant le saladier : arrêter dès l''homogénéité, quelques traînées blanches valent mieux qu''un appareil retombé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Remplir le moule aux deux tiers de sa hauteur, jamais davantage, égaliser la surface et passer le pouce ou la pointe d''un couteau dans une rainure le long de la paroi pour décoller l''appareil du bord et l''aider à monter droit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Enfourner 35 minutes en gardant la porte fermée pendant les vingt premières : le soufflé est prêt lorsqu''il dépasse largement le moule, que le dessus est bien doré et que le cœur tremble encore très légèrement quand on remue le moule. Passer directement du four à la table, il commence à redescendre au bout de deux à trois minutes.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-056', 'recipe_family', 'Soufflé au fromage',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-056', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Soufflés individuels : répartir l''appareil dans six ramequins beurrés et chemisés de gruyère, cuisson ramenée à 18-20 minutes.','Fromage plus typé : remplacer tout ou partie de l''emmental par un comté vieux, ou ajouter une soixantaine de grammes de mimolette vieille comme le fait l''une des sources du dossier.','Version express sans roux relevée dans le corpus : œufs battus en omelette avec fromage blanc, fécule et fromage râpé, versés dans un moule huilé — plus dense, plus rustique, et sans véritable levée.','Soufflé aux herbes : une cuillerée de ciboulette ou d''estragon ciselé ajoutée aux jaunes, sans jamais dépasser cette dose sous peine d''alourdir l''appareil.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-056","variants":["Soufflés individuels : répartir l''appareil dans six ramequins beurrés et chemisés de gruyère, cuisson ramenée à 18-20 minutes.","Fromage plus typé : remplacer tout ou partie de l''emmental par un comté vieux, ou ajouter une soixantaine de grammes de mimolette vieille comme le fait l''une des sources du dossier.","Version express sans roux relevée dans le corpus : œufs battus en omelette avec fromage blanc, fécule et fromage râpé, versés dans un moule huilé — plus dense, plus rustique, et sans véritable levée.","Soufflé aux herbes : une cuillerée de ciboulette ou d''estragon ciselé ajoutée aux jaunes, sans jamais dépasser cette dose sous peine d''alourdir l''appareil."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-056', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ad8cc13d3b8fa54788417130362746ce'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["fromage affiné","beurre","jaune d''œuf"],"aroma_families":["lactée","beurrée","épicée douce"],"target_textures":["mousseux","aérien","croûte dorée","cœur crémeux"],"signature_ingredients":["Œuf cru","Gruyère râpé","Emmental râpé"],"identity_guardrails":["Les blancs doivent être montés à part et incorporés à la maryse en fin d''appareil : mélangés au batteur ou battus avec les jaunes, la préparation ne lève plus et devient une omelette au four.","Le fromage à pâte pressée cuite râpé, emmental et gruyère, porte tout le goût du plat : sans lui il ne reste qu''un soufflé nature.","La base doit être une béchamel épaisse au beurre et à la farine, seule assez ferme pour tenir les bulles d''air ; un liant à la fécule délayée donne une texture caoutchouteuse hors identité.","Le moule se remplit aux deux tiers au maximum et la porte du four reste fermée en début de cuisson, sinon la levée s''effondre."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Tarte à l''oignon', 'tarte a l oignon', 'France', 'France',
     'meal', 'tarte salée', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Tarte à l''oignon', 'Fond de pâte feuilletée garni d''oignons longuement fondus avec lardons dans un appareil crème-œufs', ds.id, 'SRC-057',
    'Myko', 'editorial', 6, 20, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '1cf33ba4dc676a639fbeef89738c4e8d',
    '{"sweet":3,"salty":3,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['oignon compoté sucré','lard fumé','crème cuite']::text[],
    ARRAY['allium doux','fumé','lacté','beurré']::text[], ARRAY['feuilletage croustillant','appareil crémeux tout juste pris','oignons fondants']::text[],
    ARRAY['Oignon jaune cru','Crème fraîche liquide entière','Pâte feuilletée crue']::text[], ARRAY['Sans oignon jaune longuement compoté à feu doux jusqu''au blond, ce n''est plus une tarte à l''oignon mais une quiche quelconque.','L''appareil œuf-crème doit rester salé et prendre au four : le remplacer par du fromage fondu ou une sauce blanche change de plat.','La garniture doit reposer sur un fond de pâte cuit dans un moule, jamais sur une base de pain ou de pizza.']::text[],
    ARRAY['mijotage','réduction','cuisson au four']::text[], ARRAY['Version alsacienne stricte : supprimer les lardons et râper un peu de muscade dans l''appareil œuf-crème.','Tarte à l''oignon au chèvre : disposer des rondelles de Fromage de chèvre bûche sur la compotée avant de verser l''appareil.','Version méridionale : parfumer la compotée d''Herbes de Provence séderisées — ici, une cuillère d''Herbes de Provence séchées ajoutée en fin de compotée.','Compotée poussée plus loin au miel, étalée seule sur le feuilletage sans appareil œuf-crème, façon tarte fine à servir tiède.']::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se garde trois jours au réfrigérateur entre 0 et 4 °C, filmée une fois complètement refroidie, et se réchauffe dix minutes à 160 °C pour que le feuilletage retrouve son croustillant. La congélation est possible sur la tarte cuite et refroidie, deux mois maximum, mais l''appareil œuf-crème relâche un peu d''eau à la décongélation et la pâte ramollit : la réchauffer alors directement à 180 °C sans décongélation préalable.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
