      LIMIT 1),
     'Miel', 10, 'g', 'optional',
     'assaisonnement', true, 9);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir environ 270 g d''oignons entiers, c''est-à-dire trois beaux oignons tels qu''on les achète : une fois pelés et parés, il en reste les 240 g de chair nette utilisés ici. Les couper en deux dans la hauteur puis les émincer en demi-lunes fines et régulières.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire chauffer l''huile d''olive dans une large sauteuse, y jeter les oignons avec le miel et une petite pincée de sel, couvrir et laisser suer huit minutes à feu doux, le temps qu''ils rendent leur eau et s''affaissent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Retirer le couvercle, ajouter les lardons et poursuivre douze minutes à feu moyen en remuant régulièrement, jusqu''à ce que l''humidité se soit évaporée et que les oignons soient blonds et translucides, sans jamais brunir. Débarrasser dans un plat et laisser tiédir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Porter le four à 200 °C. Étaler la pâte avec son papier au fond d''un moule de vingt-six centimètres, piquer le fond à la fourchette et plaquer les bords contre la paroi.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Casser deux gros œufs, soit environ cent dix grammes coquille comprise pour les cent grammes d''œuf de la liste, et les fouetter avec la crème jusqu''à obtenir un appareil homogène. Saler, poivrer, goûter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Répartir la compotée tiède sur le fond de pâte en couche égale, verser l''appareil par-dessus pour qu''il s''insinue entre les oignons, puis enfourner trente minutes : la crème doit être prise au centre et le pourtour du feuilletage bien doré.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Sortir la tarte et la laisser reposer une dizaine de minutes sur une grille avant de la découper, le temps que la garniture se raffermisse et que le dessous du feuilletage sèche.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-057', 'recipe_family', 'Tarte à l''oignon',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-057', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version alsacienne stricte : supprimer les lardons et râper un peu de muscade dans l''appareil œuf-crème.','Tarte à l''oignon au chèvre : disposer des rondelles de Fromage de chèvre bûche sur la compotée avant de verser l''appareil.','Version méridionale : parfumer la compotée d''Herbes de Provence séderisées — ici, une cuillère d''Herbes de Provence séchées ajoutée en fin de compotée.','Compotée poussée plus loin au miel, étalée seule sur le feuilletage sans appareil œuf-crème, façon tarte fine à servir tiède.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-057","variants":["Version alsacienne stricte : supprimer les lardons et râper un peu de muscade dans l''appareil œuf-crème.","Tarte à l''oignon au chèvre : disposer des rondelles de Fromage de chèvre bûche sur la compotée avant de verser l''appareil.","Version méridionale : parfumer la compotée d''Herbes de Provence séderisées — ici, une cuillère d''Herbes de Provence séchées ajoutée en fin de compotée.","Compotée poussée plus loin au miel, étalée seule sur le feuilletage sans appareil œuf-crème, façon tarte fine à servir tiède."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-057', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('1cf33ba4dc676a639fbeef89738c4e8d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":3,"salty":3,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["oignon compoté sucré","lard fumé","crème cuite"],"aroma_families":["allium doux","fumé","lacté","beurré"],"target_textures":["feuilletage croustillant","appareil crémeux tout juste pris","oignons fondants"],"signature_ingredients":["Oignon jaune cru","Crème fraîche liquide entière","Pâte feuilletée crue"],"identity_guardrails":["Sans oignon jaune longuement compoté à feu doux jusqu''au blond, ce n''est plus une tarte à l''oignon mais une quiche quelconque.","L''appareil œuf-crème doit rester salé et prendre au four : le remplacer par du fromage fondu ou une sauce blanche change de plat.","La garniture doit reposer sur un fond de pâte cuit dans un moule, jamais sur une base de pain ou de pizza."],"profile_note":null}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
