  CROSS JOIN unnest(ARRAY['Version volaille de chefsimon.com : une partie du porc remplacee par du Blanc de poulet cru, sans peau juste colore a la poele, taille en lanieres et monte en etages entre deux couches de farce.','Version meridionale : ajout de Poivron rouge frais confit et d''olives detaillees, incorpores en fin de melange pour garder les morceaux entiers.','Version 750g.com en bocaux : la farce est repartie dans des bocaux cuits au bain-marie 45 minutes a 200 degres, puis coloree 10 minutes a decouvert.','Version douce : quelques miettes de Pain d''epices dans la farce, qui apportent une note miel-epices et arrondissent le poivre.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-058","variants":["Version volaille de chefsimon.com : une partie du porc remplacee par du Blanc de poulet cru, sans peau juste colore a la poele, taille en lanieres et monte en etages entre deux couches de farce.","Version meridionale : ajout de Poivron rouge frais confit et d''olives detaillees, incorpores en fin de melange pour garder les morceaux entiers.","Version 750g.com en bocaux : la farce est repartie dans des bocaux cuits au bain-marie 45 minutes a 200 degres, puis coloree 10 minutes a decouvert.","Version douce : quelques miettes de Pain d''epices dans la farce, qui apportent une note miel-epices et arrondissent le poivre."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
