      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'required',
     'assaisonnement', false, 8);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'feuille de laurier sechee' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Feuille de laurier séchée', 2, 'u', 'required',
     'aromate', false, 9);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'thym frais' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Thym frais', 1, 'g', 'required',
     'aromate', false, 10);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Inciser une croix à la pointe du couteau sous chaque tomate, les plonger trente secondes dans une casserole d''eau bouillante puis aussitôt dans un saladier d''eau très froide. La peau se retire alors d''un seul geste, en partant de la croix. Ce détour de cinq minutes évite les copeaux de peau roulés qui restent dans la sauce finie et qu''aucune cuisson ne rattrape.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Couper les tomates pelées en deux à l''horizontale, presser chaque moitié dans la main au-dessus de l''évier pour chasser les graines et l''eau de végétation, puis les concasser grossièrement. On perd un peu de poids et beaucoup de temps de réduction : c''est cette eau-là qu''on passerait sinon quarante minutes à évaporer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Éplucher et émincer finement l''oignon. Le faire suer dans l''huile d''olive à feu doux pendant huit à dix minutes, en remuant de temps en temps, jusqu''à ce qu''il devienne translucide sans prendre la moindre couleur. Un oignon coloré donnerait à la sauce une amertume grillée qu''on ne cherche pas ici ; on veut son sucre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter l''ail haché et le laisser à peine trente secondes avant de verser la tomate concassée : au-delà, l''ail brûle et devient âcre. Ajouter le laurier, le thym, le sucre, le sel et le poivre, et remuer pour décoller ce qui a pris au fond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Laisser mijoter à découvert quarante minutes environ, à petits bouillons paresseux, en remuant toutes les dix minutes et en raclant le fond. La sauce est prête quand la cuillère laisse un sillon qui se referme lentement, et quand une trace d''huile perle en surface — c''est le signe que l''eau est partie et que le gras s''est séparé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Retirer les feuilles de laurier et la branche de thym, puis ajouter le basilic ciselé hors du feu. Le basilic cuit noircit et perd son parfum en quelques minutes ; ajouté à la chaleur résiduelle, il infuse sans se défaire. Goûter et rectifier le sel maintenant, la sauce ayant concentré tout ce qu''elle contenait.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Pour une sauce lisse, passer au moulin à légumes grille fine plutôt qu''au mixeur : la lame incorpore de l''air et fait virer le rouge à l''orange pâle. Pour une sauce de pizza ou de gratin, la laisser telle quelle — les morceaux tiennent mieux à la cuisson au four.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-001', 'recipe_family', 'Sauce tomate',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-001', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Tomates pelées en conserve à la place des tomates fraîches hors saison (marmiton)','Échalote à la place de l''oignon, et quatre gousses d''ail pour un accent nettement plus aillé (marmiton)','Origan séché ajouté avec le laurier, dans la version qui garnit une pizza (marmiton, 750g)','Un cube de bouillon fondu dans la sauce, qui la sale et l''appuie en une fois (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
