  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'required',
     'assaisonnement', false, 9);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Laver les tomates et les couper en quartiers sans les peler ni les épépiner : le coulis passera au tamis, qui retiendra peau et pépins bien mieux que les doigts. Choisir des tomates allongées si le marché en propose — deux sources sur six les nomment expressément, parce qu''elles portent moins d''eau et plus de chair à poids égal.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Éplucher et émincer l''oignon, dégermer et écraser les gousses d''ail sous la lame. Les mettre à chauffer dans l''huile d''olive à feu moyen deux ou trois minutes, le temps qu''ils sentent, sans chercher la coloration.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser les quartiers de tomate, ajouter le thym, le sel, le sucre et le poivre, et monter le feu jusqu''à ce que l''ensemble bouillonne. Le sucre n''adoucit pas le coulis : il neutralise l''acidité que la réduction va concentrer, et sans lui un coulis très réduit pique.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Baisser à feu moyen et laisser cuire trente minutes à découvert, en écrasant les quartiers à la cuillère de bois au bout de dix minutes pour qu''ils rendent leur jus. Le volume doit descendre d''environ un tiers ; les morceaux ne doivent plus tenir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Retirer la branche de thym, ajouter le basilic ciselé et laisser infuser cinq minutes hors du feu, couvercle posé. Puis passer la préparation au moulin à légumes grille fine, ou au tamis en foulant à la louche. Ce passage est ce qui fait le coulis : peaux et pépins restent dans la grille, et la texture devient une crème lisse et fluide.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Remettre le coulis sur le feu deux à trois minutes s''il paraît trop liquide après le tamisage, qui rend toujours un peu d''eau. Goûter et rectifier le sel en dernier, le passage au tamis ayant retiré du volume et donc concentré l''assaisonnement.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-002', 'recipe_family', 'Coulis de tomates',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-002', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
