      ('content', to_jsonb('32875fba1f2cc48d968398c547743058'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"nutty_savory","scores":{"sweet":1,"salty":2,"acidic":1,"bitter":0,"umami":1,"heat":0,"pungency":0,"richness":2,"freshness":0,"intensity":2},"dominant_flavors":["blé","levure","huile d’olive"],"aroma_families":["céréalier","levure","fruité olive"],"target_textures":["croûte souple","moelleux"],"signature_ingredients":["Farine de blé T55","Levure boulangère sèche"],"identity_guardrails":["Une pâte à pizza lève : sans levure boulangère et sans pousse, c''est une abaisse, pas une pizza","Elle s''étale à la main et jamais au rouleau, qui écrase l''alvéolage du bord","Aucun œuf, aucun lait, aucun beurre : ce qui gras dans cette pâte est l''huile d''olive","Hydratation autour de 60 % — une pâte sèche ne s''étend pas et se rétracte au four"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
