  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-004', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('e43f1f2801324e3036059fc5bd88c09c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"nutty_savory","scores":{"sweet":0,"salty":2,"acidic":0,"bitter":0,"umami":1,"heat":0,"pungency":0,"richness":4,"freshness":0,"intensity":2},"dominant_flavors":["beurre","blé"],"aroma_families":["beurre","céréalier"],"target_textures":["croûte de chapelure cassante","friable"],"signature_ingredients":["Farine de blé T55","Beurre doux"],"identity_guardrails":["Le beurre pèse la moitié de la farine : les sept sources du dossier le disent sans exception, et c''est ce rapport qui fait une brisée","Le beurre entre froid et en cubes ; fondu, la pâte devient dure et cesse d''être brisée","On ne pétrit pas : la pâte est rassemblée, pas travaillée","Aucun sucre dans la version de base — la brisée sucrée est une autre pâte, et le dossier la donne comme telle"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
