     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oeuf cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Œuf cru', 1, 'u', 'required',
     'liant', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 2, 'g', 'required',
     'pâte', false, 5);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Sortir le beurre une demi-heure à l''avance : une sablée se monte au beurre POMMADE, souple sous le doigt mais jamais fondu, et c''est la première différence avec une brisée, qui exige au contraire un beurre froid. Le couper en morceaux dans un saladier et le travailler à la spatule jusqu''à la consistance d''une crème.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Ajouter le sucre et le sel, et travailler encore une minute jusqu''à ce que le mélange blanchisse légèrement. Le sucre se dissout dans le beurre à ce stade, ce qui donne le grain court de la pâte finie ; ajouté plus tard avec la farine, il reste en cristaux et la pâte devient granuleuse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Incorporer l''œuf entier et mélanger jusqu''à ce qu''il soit complètement absorbé. La masse peut sembler tranchée pendant quelques secondes, le temps que le beurre reprenne l''eau de l''œuf ; continuer, elle se rassemble.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser la farine en une fois et mélanger le moins possible, à la spatule d''abord puis à la main, en s''arrêtant dès que la pâte est homogène. Chaque tour de main supplémentaire développe le gluten, qui rendra la pâte élastique et la fera rétracter au four : la sablée doit rester courte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Aplatir en disque de deux centimètres, emballer et réserver au moins une heure au réfrigérateur. Cette pâte est beaucoup plus molle qu''une brisée à cause du sucre et de l''œuf ; sans ce repos, elle est simplement impossible à abaisser.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Abaisser à quatre millimètres entre deux feuilles de papier cuisson plutôt que sur un plan fariné : la sablée colle et se déchire, et la farine ajoutée à l''abaisse la dessèche. Foncer le moule en laissant retomber la pâte dans l''angle, piquer le fond, puis remettre vingt minutes au froid avant d''enfourner — c''est la deuxième assurance contre la rétraction.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Cuire à blanc quinze minutes à 180 °C, sur billes de cuisson ou légumes secs posés sur un papier, jusqu''à une coloration blonde et uniforme. Le fond doit être sec au centre, pas seulement au bord : c''est le centre qui détrempe ensuite sous la garniture. Laisser refroidir complètement sur grille avant de démouler, la pâte n''étant cassante qu''une fois froide.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-005', 'recipe_family', 'Pâte sablée',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-005', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['À la poudre d''amandes, 30 g pour 200 g de farine, avec un beurre plus généreux (chefsimon)','Au cacao amer, 50 g pour 200 g de farine et un sucre nettement plus haut (750g)','Au jaune d''œuf seul plutôt qu''à l''œuf entier, mouillée de 5 cl d''eau ou de lait (marmiton, chefsimon)','Parfumée d''un zeste de citron râpé dans le beurre (marmiton)','Version express, deux cuillerées d''huile et deux de lait à la place d''une partie du beurre (marmiton)','Au sucre vanillé ajouté au sucre semoule (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-005","variants":["À la poudre d''amandes, 30 g pour 200 g de farine, avec un beurre plus généreux (chefsimon)","Au cacao amer, 50 g pour 200 g de farine et un sucre nettement plus haut (750g)","Au jaune d''œuf seul plutôt qu''à l''œuf entier, mouillée de 5 cl d''eau ou de lait (marmiton, chefsimon)","Parfumée d''un zeste de citron râpé dans le beurre (marmiton)","Version express, deux cuillerées d''huile et deux de lait à la place d''une partie du beurre (marmiton)","Au sucre vanillé ajouté au sucre semoule (750g)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-005', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('aa2e76c639a01d62f26c7d330654fc93'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"sweet_spiced","scores":{"sweet":4,"salty":1,"acidic":0,"bitter":0,"umami":0,"heat":0,"pungency":0,"richness":4,"freshness":0,"intensity":2},"dominant_flavors":["beurre","sucre","blé"],"aroma_families":["beurre","céréalier","grillé"],"target_textures":["croûte de chapelure cassante","sans fibre"],"signature_ingredients":["Beurre doux","Sucre semoule","Farine de blé T55"],"identity_guardrails":["Le beurre est pommade, pas froid : c''est le crémage beurre-sucre qui donne le grain sablé","Un œuf entier pour 250 g de farine, comme dans cinq sources sur sept — au jaune seul c''est une autre pâte","Un sucre franc, autour de 85 g pour 250 g de farine : une sablée peu sucrée est une brisée","On ne pétrit pas après l''ajout de la farine, sous peine d''une pâte élastique qui se rétracte"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
