  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-007', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('e3aa671ba40f69234cbd7f4804673b46'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"brothy_umami","scores":{"sweet":2,"salty":2,"acidic":0,"bitter":1,"umami":2,"heat":0,"pungency":0,"richness":0,"freshness":2,"intensity":2},"dominant_flavors":["légume infusé","poireau","carotte"],"aroma_families":["végétal cuit","allium doux","thym"],"target_textures":["bouillon_clair"],"signature_ingredients":["Poireau cru","Carotte crue","Céleri branche cru"],"identity_guardrails":["Départ à l''eau froide et frémissement seul : un bouillon qui bout devient trouble et le reste","Il se filtre, et les légumes se jettent — un bouillon servi avec ses légumes est une soupe","Salé bas, parce qu''il repartira dans un plat qui aura son propre sel","Aucune matière grasse : rien ne revient avant le mouillement"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
