  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-008', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('229139c25fb7fc2b6b8e0291e7fa4a1e'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"smoky_sweet","scores":{"sweet":4,"salty":2,"acidic":3,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":2,"freshness":0,"intensity":3},"dominant_flavors":["oignon caramélisé","vinaigre","sucre cuit"],"aroma_families":["oignon compoté","vinaigré","caramel"],"target_textures":["fondant","nappant"],"signature_ingredients":["Oignon jaune cru","Vinaigre de vin rouge","Sucre semoule"],"identity_guardrails":["L''oignon fond puis colore : sauté vite à feu vif il grille au lieu de confire, et le condiment devient amer","Un acide franc en fin de cuisson — sans lui c''est une simple compotée d''oignons, pas un confit","Le sucre reste une pointe, autour de 1 % du poids d''oignon : c''est l''oignon qui sucre, pas le sucrier","Les lamelles restent visibles ; réduit en purée, ce n''est plus le même produit"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
