       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-009', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux champignons des bois — trompettes de la mort, cèpes — mêlés aux champignons de Paris (marmiton, 750g)','Additionnée d''un oignon en plus des échalotes (marmiton)','Déglacée au vin blanc et liée d''un peu de crème, pour une duxelles de farce (marmiton, 750g)','À l''ail et au piment d''Espelette, en farce de légume (chefsimon)','À l''estragon et au mascarpone, montée en garniture de feuilleté (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
