      ('sensory_contract', '{"profile":"fresh_acidic","scores":{"sweet":1,"salty":2,"acidic":3,"bitter":0,"umami":1,"heat":1,"pungency":3,"richness":4,"freshness":4,"intensity":3},"dominant_flavors":["avocat","citron vert","oignon cru","coriandre"],"aroma_families":["végétal frais","agrume","coriandre","allium"],"target_textures":["crémeux","dés fondants gardant leur forme"],"signature_ingredients":["Avocat frais","Jus de citron vert frais","Coriandre fraîche"],"identity_guardrails":["L''avocat s''écrase à la fourchette et garde des morceaux : mixé, ce n''est plus un guacamole","Le citron vert entre en premier, sur la chair nue, sinon la couleur est perdue","Aucune crème, aucun fromage frais, aucune mayonnaise : le gras est celui du fruit","Il se mange le jour même — un guacamole n''est pas une conserve"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
