     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'moutarde de dijon' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Moutarde de Dijon', 10, 'g', 'required',
     'émulsifiant', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'vinaigre de vin rouge' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Vinaigre de vin rouge', 10, 'ml', 'required',
     'acidité', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 2, 'g', 'required',
     'assaisonnement', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'required',
     'assaisonnement', false, 6);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Sortir les œufs et l''huile une demi-heure à l''avance. C''est la précaution qui décide de tout : un jaune froid et une huile à température ambiante n''émulsionnent pas, et neuf mayonnaises ratées sur dix le sont pour cette seule raison.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Séparer les jaunes des blancs et les mettre dans un bol à fond rond, assez étroit pour que le fouet travaille dans peu de matière au départ. Ajouter la moutarde, le sel et le poivre, et fouetter vingt secondes jusqu''à ce que le mélange soit lisse et pâlisse un peu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser l''huile GOUTTE À GOUTTE au début, en fouettant sans arrêt, jusqu''à ce que le mélange épaississe visiblement — cela demande à peine deux cuillerées à soupe. C''est ce premier tiers qui construit l''émulsion : chaque goutte doit être absorbée avant la suivante, faute de quoi l''huile forme des gouttelettes trop grosses que le jaune ne peut plus tenir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Une fois la sauce prise et ferme, verser le reste de l''huile en filet mince et continu, en fouettant toujours. Le rythme peut s''accélérer, mais le filet ne doit jamais devenir un flot : une mayonnaise qui tranche le fait presque toujours dans les vingt dernières millilitres, par excès de confiance.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter le vinaigre en fin de montage et fouetter dix secondes. La sauce blanchit et se détend d''un cran : c''est normal et c''est le but, une mayonnaise trop serrée n''a pas de goût et se tartine mal. Goûter et rectifier le sel.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Si la mayonnaise tranche — l''huile se sépare et la sauce redevient liquide —, ne pas la jeter : mettre une cuillerée à café de moutarde dans un bol propre et y verser la sauce tranchée goutte à goutte en fouettant, exactement comme on avait versé l''huile. Elle reprend à tous les coups.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-019', 'recipe_family', 'Mayonnaise maison',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-019', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
