  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-019', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('d7e3316189af1da4c3beb66a108cb97a'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":0,"salty":2,"acidic":2,"bitter":0,"umami":1,"heat":0,"pungency":3,"richness":5,"freshness":0,"intensity":3},"dominant_flavors":["moutarde","jaune d’œuf","vinaigre"],"aroma_families":["moutarde","œuf cuit","vinaigré"],"target_textures":["crémeux","nappant"],"signature_ingredients":["Jaune d''œuf cru","Moutarde de Dijon","Huile végétale"],"identity_guardrails":["Tous les ingrédients à la même température, sinon l''émulsion ne prend pas","L''huile entre goutte à goutte au début : c''est le premier tiers qui fait la sauce","Huile neutre et non huile d''olive, qui amertume en émulsionnant","Jaunes crus : la sauce se garde deux jours au froid et pas davantage"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
