      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'required',
     'assaisonnement', false, 5);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Sortir le beurre une heure à l''avance et le laisser venir à température ambiante, jusqu''à ce qu''il cède sous le doigt sans être brillant. Un beurre fondu, même à moitié, ne reprend jamais sa texture : il ressort grumeleux et rend son eau. C''est la seule difficulté de cette recette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Laver et sécher le persil, retirer les grosses tiges et le hacher très finement. Le sécher est plus important qu''il n''en a l''air : des feuilles mouillées apportent de l''eau que le beurre n''absorbe pas, et le boudin se délite à la coupe.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Travailler le beurre seul à la fourchette ou à la spatule dans un bol, deux minutes, jusqu''à obtenir une pommade lisse et homogène. Ajouter le sel et le poivre et mélanger — le sel doit se dissoudre maintenant, avant l''arrivée du liquide.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Incorporer le jus de citron EN TROIS FOIS, en travaillant bien entre chaque ajout. Versé d''un coup, il perle et refuse d''entrer ; ajouté par tiers, le beurre l''absorbe et reste lié. Ajouter le persil en dernier et mélanger juste assez pour le répartir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Déposer le beurre sur une feuille de papier cuisson ou de film alimentaire, le rassembler en boudin d''environ trois centimètres de diamètre, puis rouler en serrant et en tordant les deux extrémités comme un bonbon. Le serrage chasse les bulles d''air, qui feraient rancir le beurre plus vite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Raffermir au moins une heure au réfrigérateur avant de trancher en rondelles d''un demi-centimètre. Poser une rondelle sur la viande, le poisson ou les légumes À LA SORTIE du feu et non pendant la cuisson : le beurre doit fondre sur l''assiette, pas dans la poêle, où il brûlerait et où le citron s''évaporerait.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-021', 'recipe_family', 'Beurre maître d''hôtel',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-021', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['À l''échalote ciselée, un demi-échalote pour quatre (marmiton)','Aux herbes mêlées — cerfeuil, persil, ciboulette — et au vinaigre à l''échalote (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-021","variants":["À l''échalote ciselée, un demi-échalote pour quatre (marmiton)","Aux herbes mêlées — cerfeuil, persil, ciboulette — et au vinaigre à l''échalote (750g)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-021', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('042bfcc74dc5b8cc33cbc66e6eb25eed'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"rich_savory","scores":{"sweet":0,"salty":3,"acidic":2,"bitter":0,"umami":1,"heat":0,"pungency":1,"richness":5,"freshness":3,"intensity":3},"dominant_flavors":["beurre","persil","citron"],"aroma_families":["beurre","herbacé","agrume"],"target_textures":["fondant","crémeux"],"signature_ingredients":["Beurre doux","Persil frais","Jus de citron frais"],"identity_guardrails":["Le beurre est pommade et jamais fondu : fondu, il ne reprend pas et rend son eau","Le persil est la seule herbe — avec cerfeuil et ciboulette c''est un beurre aux herbes, autre chose","Le citron entre en trois fois, faute de quoi il perle et le beurre se sépare","La rondelle se pose hors du feu, sur l''assiette"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Poulet rôti', 'poulet roti', 'France', 'France',
     'meal', 'volaille', 'named_traditional_dish', 'rich_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Poulet rôti', 'Poulet entier beurré, aillé et thymé, rôti une heure et arrosé de son jus, reposé avant découpe', ds.id, 'RAP-022',
    'Myko', 'editorial', 4, 15, 60, 'facile',
    NULL, NULL,
    'B', 'candidate', '66a3e5f74d4f745e9ae9dec97c63fab0',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":0,"intensity":3}'::jsonb, ARRAY['poulet rôti','beurre','ail','thym']::text[],
    ARRAY['poulet','beurre','aillé','thym']::text[], ARRAY['croûte croustillante','chair_moelleuse']::text[],
    ARRAY['Poulet entier cru','Beurre doux','Thym frais']::text[], ARRAY['La peau doit être sèche avant le four : mouillée, elle ne croustille jamais','Le beurre passe sous la peau des blancs, sinon la chair blanche sèche avant que les cuisses soient cuites','Quinze minutes de repos avant la découpe, faute de quoi le jus part dans la planche','La quantité déclarée est le rendement en viande et peau — l''achat, lui, est un poulet de 1,4 kg']::text[],
    ARRAY['rôtissage','cuisson au four','repos','déglaçage']::text[], ARRAY['Avec vingt pommes de terre enfournées autour, qui cuisent dans le jus (marmiton, 750g)','En cocotte au four, deux oignons et 25 cl de bouillon de volaille, deux heures à couvert (marmiton)','Aux herbes de Provence à la place du thym (marmiton, 750g)','À l''huile neutre plutôt qu''au beurre (marmiton, chefsimon)','En papillote de film de cuisson, façon poulet de Bresse (chefsimon)','Servi sur un lit de roquette avec un trait de vinaigre de vin rouge dans le jus (750g)']::text[], ARRAY['lait']::text[],
    'La chair découpée se garde 3 jours au réfrigérateur en boîte fermée, et c''est là que ce plat devient une base : 300 g de restes suffisent aux quesadillas ou aux wraps de ce lot. Se congèle 3 mois, effilochée et à plat. La carcasse se garde 24 heures au froid ou se congèle telle quelle pour un fond. Ne jamais laisser le poulet cuit plus de deux heures à température ambiante, ni le réchauffer deux fois.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poulet entier cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poulet entier cru', 1000, 'g', 'required',
     'protéine', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'beurre doux' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Beurre doux', 50, 'g', 'required',
     'matière grasse', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'ail cru entier' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Ail cru entier', 18, 'g', 'required',
     'aromatique', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 8, 'g', 'required',
     'assaisonnement', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'thym frais' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Thym frais', 6, 'g', 'required',
     'aromate', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'required',
     'assaisonnement', false, 6);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Acheter un poulet de 1,4 kg prêt à cuire : il rendra environ un kilo de viande et de peau, l''os pesant le reste — c''est ce kilo-là que la liste d''ingrédients déclare. Le sortir du réfrigérateur une heure avant de l''enfourner : une volaille glacée met vingt minutes de plus à cuire, et sa peau ne dore pas tant que le cœur est froid.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Sécher le poulet à l''intérieur et à l''extérieur avec du papier absorbant, sans le rincer. La peau doit être franchement sèche : l''eau de surface se transforme en vapeur au four et la vapeur, c''est exactement le contraire d''une peau croustillante.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Préchauffer le four à 210 °C. Malaxer le beurre mou avec la moitié du sel, le poivre et les feuilles de deux branches de thym, puis en glisser la moitié SOUS LA PEAU des blancs, en décollant celle-ci du bout des doigts par l''ouverture du cou. Étaler le reste sur toute la surface. Le beurre sous la peau arrose la chair blanche de l''intérieur, là où elle sèche en premier.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Saler le reste de la surface et l''intérieur, glisser dans la cavité les gousses d''ail en chemise et les branches de thym restantes. Poser le poulet SUR LE CÔTÉ dans un plat, une cuisse vers le haut, plutôt que sur le dos.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Enfourner vingt minutes à 210 °C, retourner sur l''autre flanc pour vingt minutes encore, puis finir vingt minutes sur le dos en baissant à 190 °C. Cette rotation est ce qui règle le problème central du poulet rôti : les cuisses demandent plus de chaleur que les blancs, et les tenir sur le côté les expose pendant que les blancs cuisent doucement, arrosés par le beurre qui descend.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Arroser du jus du plat à chaque rotation, à la cuillère ou à la poire. Vérifier la cuisson en piquant l''articulation de la cuisse : le jus qui perle doit être clair et non rosé. Si la peau dore trop vite, couvrir d''une feuille d''aluminium sans serrer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Sortir le poulet et le laisser reposer quinze minutes sur une planche, couvert sans serrer. Ce repos n''est pas une politesse : découpé à la sortie du four, il perd son jus dans la planche, et la chair blanche devient sèche en cinq minutes. Pendant ce temps, déglacer le plat d''un fond d''eau chaude en grattant les sucs, ce qui fait le jus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Découper en commençant par les cuisses, puis lever les blancs en suivant le bréchet. Garder la carcasse : elle vaut un fond de sauce, et les 300 g de chair qui restent sur un poulet de 1,4 kg font les quesadillas ou les wraps du lendemain.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-022', 'recipe_family', 'Poulet rôti',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-022', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
