  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Préchauffer le four à 180 °C et poser une casserole d''eau à chauffer. Beurrer généreusement quatre ramequins jusqu''au bord supérieur, sans oublier les deux derniers centimètres, qui sont justement là où le blanc s''accroche et déchire au démoulage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Verser au fond de chaque ramequin une cuillerée à soupe de crème, soit environ 30 g, et poivrer. Cette couche fait deux choses : elle isole le jaune du contact direct avec la porcelaine brûlante, et elle donne le fond onctueux qu''on récupère à la mouillette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Casser un œuf dans une tasse avant de le verser dans le ramequin, jamais directement : une coquille qui tombe dans le ramequin s''y pêche mal, et un jaune crevé ne se rattrape pas. Faire glisser l''œuf sur la crème sans le laisser tomber de haut.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Saler le BLANC seulement, en évitant le jaune. Le sel posé sur un jaune y creuse des taches claires et le durcit en surface pendant l''attente, ce qui se voit à la cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Poser les ramequins dans un plat à bords hauts et verser de l''eau bouillante jusqu''à mi-hauteur. Le bain-marie n''est pas une précaution de style : il plafonne la température autour de l''ébullition et laisse au blanc le temps de prendre pendant que le jaune, plus lent, reste liquide. Sans lui les bords sont caoutchouteux avant que le centre soit pris.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Enfourner dix minutes exactement et surveiller à partir de huit. L''œuf est prêt quand le blanc est opaque et tremble encore légèrement au centre, le jaune restant brillant et mobile. Un blanc entièrement figé signifie que le jaune l''est aussi.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Sortir les ramequins du bain-marie AUSSITÔT, avec un torchon, et les poser sur une assiette froide : laissés dans l''eau chaude, ils continuent de cuire trois bonnes minutes et le jaune prend. Servir immédiatement avec des mouillettes de pain grillé.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-025', 'recipe_family', 'Œufs cocotte',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-025', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au bacon, une tranche par ramequin, et gruyère râpé sur le dessus (marmiton, chefsimon)','Au saumon fumé, une tranche déposée sous l''œuf (marmiton)','Au jambon blanc et au gruyère râpé (marmiton)','À la portugaise, sur un lit de tomate, poivron et oignon fondus au thym (chefsimon)','Au foie gras mi-cuit, 25 g par ramequin, en version de fête (750g)','Au beurre d''escargots congelé à la place de la crème (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-025","variants":["Au bacon, une tranche par ramequin, et gruyère râpé sur le dessus (marmiton, chefsimon)","Au saumon fumé, une tranche déposée sous l''œuf (marmiton)","Au jambon blanc et au gruyère râpé (marmiton)","À la portugaise, sur un lit de tomate, poivron et oignon fondus au thym (chefsimon)","Au foie gras mi-cuit, 25 g par ramequin, en version de fête (750g)","Au beurre d''escargots congelé à la place de la crème (750g)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-025', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('eb77c8b6383e337b98e8f38915915f20'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_delicate","scores":{"sweet":1,"salty":2,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":0,"richness":5,"freshness":0,"intensity":2},"dominant_flavors":["œuf","crème","beurre"],"aroma_families":["œuf cuit","lactée","beurre"],"target_textures":["jaune d''œuf coulant","blanc ferme et lisse","crémeux"],"signature_ingredients":["Œuf cru","Crème fraîche liquide entière","Beurre doux"],"identity_guardrails":["Bain-marie obligatoire : sans lui les bords caoutchoutent avant que le blanc prenne","Le jaune reste coulant — un jaune cuit fait un œuf en cocotte raté, pas un autre plat","Un œuf par ramequin, les huit sources du dossier sans exception","Sortir du bain-marie dès la fin de la cuisson, sinon la chaleur résiduelle finit le jaune"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
