  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Inciser une croix sous les tomates, les ébouillanter trente secondes puis les rafraîchir à l''eau glacée et les peler. Les couper en deux, presser les graines et l''eau, et concasser la chair. C''est la demi-heure de préparation que les deux sources déclarent, et il n''y a pas de raccourci — sauf à partir d''une sauce tomate déjà faite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Fendre le piment en deux dans la longueur et retirer les graines et les cloisons blanches si l''on veut doser le feu : la capsaïcine y est concentrée bien plus que dans la chair. L''émincer finement. Peler et émincer l''ail.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer l''huile d''olive dans une sauteuse à feu doux et y mettre l''ail et le piment ENSEMBLE, à froid ou presque. Il ne s''agit pas de les faire revenir mais de les faire infuser dans l''huile deux ou trois minutes, jusqu''à ce que l''ail blondisse à peine : c''est cette huile parfumée qui est le socle du plat, et un ail brûlé la rend amère pour de bon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter la tomate concassée, saler et poivrer, monter le feu jusqu''au bouillonnement puis laisser réduire quinze minutes à feu moyen, à découvert, en remuant de temps en temps. La sauce est prête quand elle nappe et qu''un sillon de spatule se referme lentement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Pendant ce temps, cuire les penne dans un grand volume d''eau bouillante salée, une à deux minutes de MOINS que le temps du paquet. Prélever une louche d''eau de cuisson avant d''égoutter : cette eau chargée d''amidon est ce qui liera la sauce aux pâtes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Verser les penne égouttées directement dans la sauteuse et les faire sauter deux minutes à feu vif avec la sauce, en ajoutant un peu d''eau de cuisson si l''ensemble s''assèche. Ce mariage final dans la poêle est ce qui distingue un plat de pâtes d''une assiette de pâtes nappées : les penne finissent de cuire dans la sauce et l''absorbent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Goûter et rectifier le piquant — un arrabbiata doit chauffer franchement en fin de bouche — puis servir aussitôt, sans fromage. Les deux sources n''en mettent pas dans la sauce, et le pecorino, quand il est là, se râpe à table.');

  INSERT INTO quality.review_tasks
