    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-026', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
