  CROSS JOIN unnest(ARRAY['Aux tomates jaunes et tomates cerises rouges, avec basilic, parmesan et un trait de vinaigre balsamique (750g)','À la poitrine fumée et à l''oignon, 125 g pour quatre, ce qui la rapproche d''une amatriciana (marmiton)','Montée au beurre plutôt qu''à l''huile d''olive, 25 g pour quatre (marmiton)','Aux fruits de mer, 400 g de mélange marin déglacés au vin blanc (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-026","variants":["Aux tomates jaunes et tomates cerises rouges, avec basilic, parmesan et un trait de vinaigre balsamique (750g)","À la poitrine fumée et à l''oignon, 125 g pour quatre, ce qui la rapproche d''une amatriciana (marmiton)","Montée au beurre plutôt qu''à l''huile d''olive, 25 g pour quatre (marmiton)","Aux fruits de mer, 400 g de mélange marin déglacés au vin blanc (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-026', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('2c0b1c6bec6abffc281a133c65659f99'::text), 'myko_v3_canonical_recipe'),
