  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Couper les tomates en quartiers épais plutôt qu''en dés, et le concombre en demi-rondelles d''un centimètre, épluché ou non selon la peau. Les morceaux d''une salade grecque sont GROS : c''est ce qui la distingue d''une salade composée, et c''est aussi ce qui l''empêche de rendre son eau en dix minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Émincer l''oignon rouge en fines demi-lunes et le laisser tremper cinq minutes dans un bol d''eau froide, puis l''égoutter. Ce bain retire l''agressivité soufrée qui, sinon, domine tout le saladier au bout d''une demi-heure — l''oignon garde son croquant et perd son mordant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Épépiner le poivron vert et le couper en fines lanières. Le vert est le poivron de cette salade et non le rouge : moins sucré, plus amer, il tient tête à la feta.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Réunir tomates, concombre, poivron, oignon et olives dans un grand saladier, saler légèrement et poivrer. Ne saler qu''à peine : la feta qui arrivera dessus est un fromage à 2,3 g de sel pour 100 g, et 180 g en apportent plus de quatre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser l''huile d''olive et le vinaigre directement sur les légumes et mélanger. Pas de vinaigrette émulsionnée ici : les deux liquides sont versés séparément, ce qui donne au fond du saladier le jus tomate-huile qu''on sauce avec du pain et qui fait la moitié du plaisir du plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Poser la feta ENTIÈRE sur le dessus, en un pavé, plutôt que de l''émietter dans la salade. C''est ainsi qu''elle se sert en Grèce, et ce n''est pas qu''une question d''allure : émiettée, elle sale l''ensemble et se noie ; posée, chacun en prélève ce qu''il veut et elle reste crémeuse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Saupoudrer l''origan sec sur la feta et l''arroser d''un dernier filet d''huile. Servir dans les vingt minutes : passé ce délai, le sel et le vinaigre ont tiré l''eau des tomates et du concombre, et le saladier est à moitié rempli de jus.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-028', 'recipe_family', 'Salade grecque',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-028', 'missing_required_count', v_missing), 'open');
  END IF;

