  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-028', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('815443d7a824a03a5cf30e5c82c5076b'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"fresh_acidic","scores":{"sweet":2,"salty":4,"acidic":3,"bitter":2,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":5,"intensity":3},"dominant_flavors":["feta","tomate","olive noire","origan"],"aroma_families":["fromage_affiné","végétal frais","aromates séchés","fruité olive"],"target_textures":["feuilles croquantes","crémeux","oignon cru croquant"],"signature_ingredients":["Feta","Concombre frais","Olive noire dénoyautée"],"identity_guardrails":["Aucune salade verte : une salade grecque n''en porte pas, et aucune des quatre sources n''en met","La feta se pose en pavé entier sur le dessus, elle ne s''émiette pas dedans","Origan sec et rien d''autre comme herbe","Gros morceaux : coupée en dés, la salade rend son eau et s''affaisse"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
