  CROSS JOIN unnest(ARRAY['À la burrata, deux boules pour quatre, avec des tomates cerises rouges et jaunes (marmiton)','De pêches jaunes et jambon de Parme, avec roquette et citron (chefsimon)','En salade de pâtes, 500 g de pâtes courtes ajoutées à la tomate et à la mozzarella (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
