  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Couper les blancs de poulet en cubes de trois centimètres et les sécher au papier absorbant. Un morceau humide ne dore pas : il rend son eau et bout dans la poêle, ce qui donne une chair grise et filandreuse au lieu d''une croûte dorée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Chauffer la moitié de l''huile à feu vif dans une sauteuse large et y saisir le poulet en DEUX FOIS, trois minutes par fournée, sans remuer pendant la première minute. Entassé, il refroidit la poêle et se met à bouillir ; c''est la faute la plus courante de cette recette. Réserver le poulet doré.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Baisser le feu, verser le reste de l''huile et y faire fondre l''oignon émincé six à huit minutes, jusqu''à ce qu''il soit translucide et commence tout juste à blondir. Les sucs laissés par le poulet se décollent au contact de l''eau que l''oignon rend.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter l''ail haché et le curry en poudre et remuer trente secondes à une minute dans le gras chaud, jusqu''à ce que l''odeur change et devienne franche. Cette torréfaction rapide est ce qui sépare un curry parfumé d''un curry poudreux : les arômes du mélange sont solubles dans la matière grasse et pas dans l''eau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser le lait de coco, gratter le fond, saler et porter à frémissement. Laisser réduire dix minutes à découvert et à feu moyen, sans bouillir — un lait de coco bouilli se sépare en huile et en grumeaux blancs. La sauce doit napper le dos d''une cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Remettre le poulet et son jus dans la sauteuse et laisser six à huit minutes de plus, à petit feu, en retournant les morceaux à mi-parcours. Le poulet finit de cuire dans la sauce, qu''il épaissit un peu en rendant ses sucs — c''est pour cela qu''on ne le cuit pas entièrement à la première saisie.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Goûter, rectifier le sel et le poivre, et servir sur du riz. Si la sauce a trop réduit, la détendre d''un fond d''eau chaude plutôt que de lait de coco, qui la relancerait en gras.');

