  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Trancher les blancs de poulet en aiguillettes d''un centimètre et demi, dans le sens de la largeur. Les sécher, les saler et les poivrer. Prélever le zeste d''un demi-citron avant de presser les citrons : le zeste porte les huiles essentielles, le jus porte l''acide, et les deux ne font pas le même travail.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Chauffer l''huile à feu vif dans une sauteuse et saisir le poulet en deux fournées, deux minutes par face, jusqu''à une belle coloration sans cuisson à cœur. Réserver : il finira dans la sauce, et un blanc cuit deux fois de bout en bout devient sec.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Baisser le feu, ajouter l''ail émincé et les feuilles de sauge dans la sauteuse et remuer trente secondes — la sauge est une herbe qui donne son parfum au gras chaud, pas au bouillon. Verser le vin blanc et gratter tout le fond à la spatule.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Laisser réduire le vin de moitié, quatre à cinq minutes, avant d''ajouter le bouillon. Cette réduction préalable n''est pas facultative : elle évacue l''alcool, qui rendrait la sauce âpre, et concentre l''acidité qui portera le citron.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter le bouillon et laisser réduire d''un tiers à feu moyen, une dizaine de minutes, puis verser la crème et poursuivre dix minutes de plus jusqu''à ce que la sauce nappe. Ne pas saler avant cette étape : le bouillon sale déjà, et une sauce réduite concentre ce qu''elle contient.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Remettre le poulet et son jus, laisser cinq minutes à petit frémissement, puis ajouter le jus de citron HORS DU FEU. C''est le geste qui décide du plat : versé dans une sauce bouillante, l''acide fait trancher la crème et perd son parfum ; ajouté hors du feu, il reste vif et la sauce reste lisse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Râper le zeste réservé par-dessus, goûter et rectifier. La sauce doit être franchement citronnée — c''est le nom du plat — et le sel doit venir soutenir l''acide plutôt que le masquer. Servir aussitôt sur un riz ou des pâtes.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-034', 'recipe_family', 'Poulet au citron',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-034', 'missing_required_count', v_missing), 'open');
  END IF;

