  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-034', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a24963ea2e7ce9e3cb8fb55e16d3c8ef'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":4,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":3,"intensity":3},"dominant_flavors":["citron","crème","poulet","sauge"],"aroma_families":["agrume","lactée","poulet","herbacé"],"target_textures":["chair_moelleuse","sauce nappante"],"signature_ingredients":["Blanc de poulet cru, sans peau","Jus de citron frais","Crème fraîche liquide entière"],"identity_guardrails":["Le jus de citron entre HORS DU FEU : versé chaud, il fait trancher la crème","Le vin réduit de moitié avant tout autre liquide, sinon la sauce reste âpre","Le poulet est saisi puis réservé, il ne cuit pas deux fois de bout en bout","Une sauce franchement citronnée : à moins de 15 ml de jus par personne, le nom ne tient plus"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
