  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Sortir les escalopes vingt minutes avant de cuire et les sécher au papier absorbant. Nettoyer les champignons au pinceau et les émincer, ciseler les échalotes très fin. Tout doit être prêt avant d''allumer le feu : la cuisson dure dix minutes en tout et il n''y aura pas de temps mort pour éplucher.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Chauffer la moitié du beurre à feu vif dans une grande poêle et saisir les escalopes salées et poivrées, deux à trois minutes par face selon l''épaisseur, jusqu''à une belle coloration. Les réserver sur une assiette tiède. La dinde est plus maigre que le poulet : au-delà de six minutes en tout elle devient sèche, et rien ne le rattrape.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Jeter les champignons dans la même poêle sans ajouter de gras et les laisser rendre leur eau à feu vif deux à trois minutes, jusqu''à ce que la poêle grésille de nouveau. Ils déglacent au passage les sucs laissés par la dinde, qui sont la base du goût de la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter le reste du beurre et les échalotes, baisser à feu moyen et laisser fondre trois minutes, jusqu''à ce que les champignons soient dorés et les échalotes translucides. Saler légèrement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser la crème, ajouter la moutarde et remuer pour la dissoudre. Laisser réduire trois à quatre minutes à petit bouillonnement, jusqu''à ce que la sauce nappe le dos d''une cuillère. La moutarde ne doit pas bouillir longtemps : au-delà de cinq minutes elle perd son piquant et ne laisse que son amertume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Remettre les escalopes et le jus qu''elles ont rendu dans la poêle, les retourner une fois dans la sauce et couper le feu au bout d''une minute. Elles finissent de chauffer dans la sauce sans y cuire davantage. Poivrer, goûter, servir aussitôt.');

