  CROSS JOIN unnest(ARRAY['Panées à la poudre d''amandes et à l''œuf, sur une crème d''oignons longuement fondus (marmiton)','Aux légumes et à la crème de curry, avec carottes, poivron rouge et raisins secs (marmiton)','Déglacée au vin blanc et parfumée à l''ail des ours (chefsimon)','Aux lardons fumés ajoutés aux champignons (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
