  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-038', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ccca14647f88caffbfc8383f471da57b'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":3},"dominant_flavors":["saumon","crème","échalote"],"aroma_families":["marin","lactée","échalote"],"target_textures":["chair nacrée et moelleuse","sauce nappante"],"signature_ingredients":["Pavé de saumon cru, sans peau","Crème fraîche liquide entière","Échalote crue"],"identity_guardrails":["Cuisson longue côté peau et courte de l''autre : c''est ce qui garde le cœur nacré","On retourne quand la cuisson a gagné les deux tiers de l''épaisseur, pas à la montre","La sauce se monte dans la poêle du poisson, sur ses sucs — dans une casserole propre, elle n''a aucun goût","Le saumon repose hors du feu avant d''être servi"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
