  CROSS JOIN unnest(ARRAY['Aux tomates fraîches et au jus de citron, à la mode du sud de l''Inde (marmiton)','À la mangue, citronnelle, gingembre et basilic thaï, sur nouilles de riz (chefsimon)','Aux courgettes et poivrons rouges, déglacés au vin blanc (chefsimon)','Au nuoc-mâm, curcuma et coriandre, avec des vermicelles de soja (750g)','À la crème fraîche plutôt qu''au lait de coco, en version express (marmiton)','Aux crevettes surgelées, décongelées et bien épongées avant de les jeter dans la sauce (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-039","variants":["Aux tomates fraîches et au jus de citron, à la mode du sud de l''Inde (marmiton)","À la mangue, citronnelle, gingembre et basilic thaï, sur nouilles de riz (chefsimon)","Aux courgettes et poivrons rouges, déglacés au vin blanc (chefsimon)","Au nuoc-mâm, curcuma et coriandre, avec des vermicelles de soja (750g)","À la crème fraîche plutôt qu''au lait de coco, en version express (marmiton)","Aux crevettes surgelées, décongelées et bien épongées avant de les jeter dans la sauce (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-039', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('6ac50392ff1b74a7e461eded706a0965'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":1,"bitter":1,"umami":4,"heat":2,"pungency":2,"richness":4,"freshness":1,"intensity":4},"dominant_flavors":["crevette","curry","lait de coco","oignon"],"aroma_families":["marin","épices chaudes","coco","oignon"],"target_textures":["chair_moelleuse","sauce nappante"],"signature_ingredients":["Crevette crue décortiquée","Lait de coco","Curry en poudre"],"identity_guardrails":["Les crevettes cuisent deux à trois minutes, en toute fin : c''est la seule règle qui compte","Crevettes crues et non déjà cuites, qui deviennent caoutchouteuses en recuisant","Le curry passe par le gras chaud avant le lait de coco","Le lait de coco frémit sans bouillir, sous peine de se séparer"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
