  CROSS JOIN unnest(ARRAY['Au four, vingt minutes à 200 °C, sans matière grasse (chefsimon)','Au son d''avoine et aux graines de coriandre pilées à la place de la chapelure (chefsimon)','Aux biscottes écrasées, panure plus fine et plus croustillante (marmiton, chefsimon)','Épicé, paprika et curcuma mêlés à la farine, avec de la farine de manioc (marmiton)','Au fromage râpé mêlé à la chapelure et au zeste de citron (chefsimon, 750g)','Panure passée au lait plutôt qu''à l''œuf entier, avec un jaune seul (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-040","variants":["Au four, vingt minutes à 200 °C, sans matière grasse (chefsimon)","Au son d''avoine et aux graines de coriandre pilées à la place de la chapelure (chefsimon)","Aux biscottes écrasées, panure plus fine et plus croustillante (marmiton, chefsimon)","Épicé, paprika et curcuma mêlés à la farine, avec de la farine de manioc (marmiton)","Au fromage râpé mêlé à la chapelure et au zeste de citron (chefsimon, 750g)","Panure passée au lait plutôt qu''à l''œuf entier, avec un jaune seul (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
