  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-041","variants":["Au tofu ferme, 300 g pour quatre, sautés à part et remis à la fin (marmiton)","Aux légumes de printemps : pointes d''asperges et mini-poireaux (750g)","Au miel et à la citronnelle dans la sauce soja (marmiton)","Aux oignons cébettes ciselés en finition (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
