    VALUES
      ('content', to_jsonb('9668d92162da95cc0aef7a5e399df729'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":2,"salty":4,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["sauce soja","sésame grillé","légumes sautés","riz"],"aroma_families":["soja","sésame_toasté","végétal grillé","céréalier"],"target_textures":["riz_moelleux","feuilles croquantes"],"signature_ingredients":["Riz cru","Sauce soja","Huile de sésame grillé"],"identity_guardrails":["Le riz doit être cuit la veille et froid : chaud, il colle et le plat rate","Feu maximum du début à la fin — un sauté à feu moyen est une poêlée","L''huile de sésame arrive hors du feu, sinon elle devient amère","La sauce soja remplace le sel : on ne sale pas en plus"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
