    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux nouilles de riz plutôt qu''aux nouilles de blé (marmiton)','Aux nouilles soba de sarrasin, avec noix de cajou (chefsimon)','Au pak choï et aux germes de soja frais, relevé de sriracha (marmiton)','À la julienne de légumes toute prête, 500 g pour quatre (marmiton)','Au poivron vert, poireau et germes de soja, à l''huile d''arachide (marmiton)','Au sirop d''érable ou au miel à la place du sucre, avec graines de sésame (chefsimon)']::text[]) AS variant(name);

