  CROSS JOIN unnest(ARRAY['Pâte coupée de froment, 150 g de blé pour 500 g de sarrasin (marmiton)','Sur galette de sarrasin achetée, garnie et réchauffée à la poêle (chefsimon)','À l''emmental râpé plutôt qu''au gruyère (chefsimon)','Parfumée d''un brin de thym sur la garniture (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
