  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-044', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('69097699586830ee88db9e0dfed31f44'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"nutty_savory","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":0,"richness":4,"freshness":0,"intensity":3},"dominant_flavors":["sarrasin","jambon","gruyère fondu","œuf"],"aroma_families":["céréalier","porc","fromage_affiné","beurre"],"target_textures":["croûte souple","fromage fondant","jaune d''œuf coulant"],"signature_ingredients":["Farine de sarrasin","Jambon blanc cuit","Œuf cru"],"identity_guardrails":["Farine de sarrasin, pas de froment : c''est ce qui fait une galette et non une crêpe","Hydratation à 230 % — deux fois celle d''une pâte à crêpes","Le jaune reste coulant et visible au centre du carré","Deux heures de repos au minimum, sans quoi la galette se déchire"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
