      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au poulet pané, avec cheddar et mayonnaise (marmiton)','Chaud, à la crème moutardée et au gruyère, passé à la poêle (marmiton)','À la mexicaine, poivrons rouge et vert, oignon, guacamole et crème fraîche (chefsimon)','Aux graines germées, courgette râpée et moutarde douce au miel (chefsimon)','Aux oignons frits et à la ciboulette, relevé d''une cuillerée de curry (marmiton)','Au fromage frais, tomates séchées, poivrons et origan, en mini-roulés (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
