  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Équeuter les haricots en cassant l''extrémité du pédoncule à la main : la queue vient, le fil aussi s''il y en a. Garder l''autre pointe, qui est fine et ne gêne pas. Des haricots verts SURGELÉS, déjà équeutés, dispensent entièrement de cette étape et de la suivante — ils sont blanchis à l''usine et se jettent directement dans la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Porter à ébullition un grand volume d''eau très salée — une cuillerée à soupe de sel par litre — et y plonger les haricots. Le volume compte : jetés dans peu d''eau, ils la refroidissent et cuisent en la remontant, ce qui les fait virer au kaki. Compter huit à dix minutes selon leur grosseur, en goûtant à huit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Les égoutter et les plonger AUSSITÔT dans un saladier d''eau glacée. Ce choc thermique fait deux choses : il arrête la cuisson au point exact où on l''a laissée, et il fixe la chlorophylle, ce qui donne le vert franc qu''un haricot laissé refroidir seul perd en dix minutes. Les égoutter à fond dès qu''ils sont froids.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Éplucher les gousses d''ail, retirer le germe et les émincer en fines lamelles plutôt que de les hacher : en lamelles elles dorent sans brûler et se mangent, hachées elles brûlent en trente secondes dans une poêle chaude.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Faire mousser le beurre dans une grande poêle à feu moyen, y jeter l''ail et le laisser blondir une minute à peine, en remuant. L''ail doit devenir doré et parfumé ; s''il brunit, tout recommencer — un ail brûlé rend le plat amer et rien ne le rattrape.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ajouter les haricots égouttés, monter le feu et sauter deux à trois minutes en secouant la poêle, jusqu''à ce qu''ils soient brillants, chauds et marqués par endroits. Saler, poivrer, goûter et servir aussitôt : ils tiennent leur croquant dix minutes et pas davantage.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-048', 'recipe_family', 'Haricots verts à l''ail',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-048', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['À la crème et au fromage frais ail et fines herbes, avec des lardons (marmiton)','Au citron et au sirop d''érable, saupoudrés de levure alimentaire et de graines de chanvre (chefsimon)','Aux haricots verts surgelés, sans équeutage ni blanchiment (marmiton)','En accompagnement d''un gigot, avec oignons, thym et laurier (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-048","variants":["À la crème et au fromage frais ail et fines herbes, avec des lardons (marmiton)","Au citron et au sirop d''érable, saupoudrés de levure alimentaire et de graines de chanvre (chefsimon)","Aux haricots verts surgelés, sans équeutage ni blanchiment (marmiton)","En accompagnement d''un gigot, avec oignons, thym et laurier (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-048', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('06ca2a0e2f66c45f97e54153d75b6b99'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":1,"heat":0,"pungency":3,"richness":3,"freshness":3,"intensity":2},"dominant_flavors":["haricot vert","ail","beurre"],"aroma_families":["végétal cuit","aillé","beurre"],"target_textures":["feuilles croquantes","fondant"],"signature_ingredients":["Haricot vert cru","Ail cru","Beurre doux"],"identity_guardrails":["Blanchiment à grande eau très salée puis eau glacée : c''est ce qui tient le vert","L''ail est émincé en lamelles et blondit sans brunir — brûlé, il gâche tout le plat","Les haricots restent croquants sous la dent","On saute deux minutes, on ne mijote pas"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
