  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux lardons fumés poêlés, liés au tapioca (marmiton)','Glacé, au yaourt nature et à la menthe, avec des mouillettes au chèvre (marmiton)','Au pamplemousse et à la menthe fraîche, monté au lait et à la crème (marmiton)','À l''échalote fondue et au bouillon plutôt qu''au lait (750g)','Aux petits pois frais écossés, à poids égal (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-049","variants":["Aux lardons fumés poêlés, liés au tapioca (marmiton)","Glacé, au yaourt nature et à la menthe, avec des mouillettes au chèvre (marmiton)","Au pamplemousse et à la menthe fraîche, monté au lait et à la crème (marmiton)","À l''échalote fondue et au bouillon plutôt qu''au lait (750g)","Aux petits pois frais écossés, à poids égal (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
