      ('sensory_contract', '{"profile":"creamy_delicate","scores":{"sweet":3,"salty":2,"acidic":0,"bitter":1,"umami":2,"heat":0,"pungency":0,"richness":3,"freshness":3,"intensity":2},"dominant_flavors":["petit pois","lait","menthe","crème"],"aroma_families":["végétal frais","lactée","herbacé"],"target_textures":["velouté lisse","sans fibre"],"signature_ingredients":["Petit pois surgelé","Lait demi-écrémé","Menthe fraîche"],"identity_guardrails":["Quinze minutes de cuisson au plus : au-delà le vert vire et le goût devient farineux","Les pois entrent surgelés, sans décongélation préalable","Le mixage est long — c''est la peau du pois qui décide de la finesse","La menthe infuse hors du feu, elle ne bout pas"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
