  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Poser les escalopes entre deux feuilles de papier cuisson et les aplatir au rouleau ou au plat d''un couteau lourd jusqu''à cinq millimètres d''épaisseur régulière. Une escalope inégale cuit à deux vitesses : la partie mince est sèche quand la partie épaisse est encore rose, et aucune panure ne rattrape cela.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Saler et poivrer la viande sur les deux faces, puis préparer trois assiettes creuses : la farine dans la première, les œufs battus à la fourchette dans la deuxième, la chapelure mélangée au parmesan finement râpé dans la troisième. Saler la viande et non la panure : le sel posé sur la chapelure la fait tomber.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Passer chaque escalope dans la farine en tapotant pour ôter l''excédent, puis dans l''œuf, puis dans le mélange chapelure-parmesan en appuyant franchement de la paume. La couche de farine sert à sécher la surface pour que l''œuf s''y accroche ; sans elle la panure se décolle en cuisant et il reste une viande nue au milieu d''une croûte flottante.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Laisser les escalopes panées reposer un quart d''heure au frais sur une grille. Ce repos n''est pas du confort : l''humidité de l''œuf gélifie la panure et la soude à la viande. Une escalope panée cuite dans la foulée perd la moitié de sa croûte dans la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Chauffer l''huile et le beurre ensemble dans une grande poêle jusqu''à ce que la mousse du beurre retombe. L''huile empêche le beurre de noircir aux 150 degrés qu''il faut atteindre ; le beurre seul brûlerait avant que la panure ne dore.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Cuire les escalopes deux par deux, quatre à cinq minutes de chaque côté, sans jamais les entasser ni les déplacer pendant la première moitié du temps. La poêle chargée refroidit, la panure boit alors le gras au lieu de le repousser, et l''escalope ressort grasse et molle. La croûte doit être brun doré, pas brun foncé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Égoutter deux minutes sur une grille — jamais sur du papier absorbant, qui retient la vapeur sous l''escalope et ramollit le dessous — et servir aussitôt avec les quartiers de citron, à presser à table. Le citron pressé d''avance détrempe la panure en trois minutes.');

  INSERT INTO quality.review_tasks
