  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-003', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('426428682947859fe44867f40a3d7922'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":0,"richness":4,"freshness":2,"intensity":3},"dominant_flavors":["veau","parmesan","beurre noisette","citron"],"aroma_families":["beurre","fromage affiné","agrume","pain grillé"],"target_textures":["croûte croustillante","tendre","contraste_léger"],"signature_ingredients":["Escalope de veau crue fine","Chapelure de blé","Parmesan affiné"],"identity_guardrails":["L''escalope doit être aplatie à cinq millimètres : c''est l''épaisseur qui permet à la viande d''être cuite au moment exact où la panure est dorée","Panure à l''anglaise en trois temps, farine comprise — sans farine la croûte se détache et le plat n''existe plus","Beurre et huile ensemble : le beurre seul brûle avant que la panure ne prenne couleur","Le citron se presse à table, jamais dans la poêle ni sur l''escalope en attente"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
