  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Porter le lait à frémissement avec le sel, le poivre et la muscade dans une casserole à fond épais. Le fond épais n''est pas un détail : la semoule attache dès qu''elle épaissit et une casserole mince donne un goût de brûlé qu''on ne rattrape pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Verser la semoule en pluie fine d''une main en fouettant de l''autre, sans arrêter. Versée d''un coup, elle prend en grumeaux que rien ne défera ensuite — la semoule gonfle en quelques secondes et emprisonne le lait sec au centre de chaque grumeau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Cuire à feu doux huit à dix minutes en remuant à la cuillère de bois, jusqu''à ce que la masse se décolle des parois et forme un bloc qui suit la cuillère. C''est le repère de la bonne texture : trop molle, elle ne se découpera pas ; trop cuite, elle devient élastique.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Retirer du feu, laisser tiédir deux minutes puis incorporer les jaunes d''œuf un à un en battant vivement, et les deux tiers du parmesan râpé. Les jaunes jetés dans la semoule bouillante coaguleraient en filaments ; deux minutes d''attente suffisent à descendre sous les 70 degrés.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Étaler la pâte sur un plat ou une plaque huilée en une couche régulière d''un centimètre et demi, lisser à la spatule mouillée, et laisser refroidir une heure au moins — la nuit au réfrigérateur convient mieux encore. Une pâte tiède se déchire à l''emporte-pièce ; une pâte froide se découpe net.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Découper des disques de cinq à six centimètres à l''emporte-pièce ou au verre, et les disposer en les faisant se chevaucher comme des tuiles dans un plat à gratin beurré. Le chevauchement double l''épaisseur sur la moitié de chaque disque : c''est ce qui donne le contraste entre les bords croustillants et le cœur fondant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Parsemer du parmesan restant, répartir le beurre en petits morceaux sur le dessus et enfourner à 200 °C pour quinze à vingt minutes, jusqu''à ce que la surface soit tachée de brun. Le beurre en morceaux, plutôt que fondu et versé, fond en descendant et arrose chaque disque au lieu de former une flaque au fond du plat. Servir dans le plat, très chaud.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-004', 'recipe_family', 'Gnocchi à la romaine',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-004', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Beurre de sauge : 100 g de beurre fondus avec dix feuilles de sauge et versés sur les gnocchis au sortir du four (chefsimon)','Moitié parmesan, moitié emmental râpé dans la pâte (marmiton)','Version à la farine : 200 g de farine et cinq œufs entiers pour un demi-litre de lait, pâte pochée puis gratinée au gruyère — une autre préparation sous le même nom (marmiton)','Semoule fine plutôt que moyenne, pour une pâte plus lisse (chefsimon, marmiton)']::text[]) AS variant(name);

