  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-004', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('57a4b876a343749b81f1ef8fa0f09371'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":0,"intensity":3},"dominant_flavors":["parmesan","lait","beurre","muscade"],"aroma_families":["lacté","fromage affiné","beurre","muscade"],"target_textures":["croûte gratinée","intérieur_fondant_ou_crémeux","contraste_léger"],"signature_ingredients":["Semoule de blé dur moyenne sèche","Lait entier","Parmesan affiné"],"identity_guardrails":["Rapport d''un pour cinq entre semoule et lait : c''est lui qui décide si la pâte se découpera ou non","La pâte doit refroidir complètement avant la découpe — tiède, elle se déchire et il n''y a plus de disques","Les disques se posent en tuiles qui se chevauchent, sinon il n''y a ni bords croustillants ni cœur fondant","Ce ne sont pas des gnocchis de pomme de terre : aucune pomme de terre n''entre ici, la semoule est le plat"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Calzone', 'calzone', 'Italie', 'Italie',
     'meal', 'pizza', 'named_traditional_dish', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Calzone', 'Pizza repliée et scellée, garnie de mozzarella, d''emmental et de champignons à la tomate', ds.id, 'VAR-005',
    'Myko', 'editorial', 4, 20, 20, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '5c2ce6ca1a51c88b6e74d5516bf2e194',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['mozzarella fondue','tomate concentrée','jambon','pâte cuite']::text[],
    ARRAY['lacté','tomate_cuite','pain grillé','champignon']::text[], ARRAY['croûte croustillante','intérieur_fondant_ou_crémeux','champignon_fondant']::text[],
    ARRAY['Farine de blé T55','Mozzarella','Jambon blanc cuit']::text[], ARRAY['C''est une pâte à pizza levée et refermée : une pâte brisée ou feuilletée en ferait un chausson, pas un calzone','La garniture doit être sèche — mozzarella égouttée, champignons précuits — sinon la vapeur détrempe la pâte de l''intérieur','Deux centimètres de bord nus pour souder, et deux fentes sur le dessus : sans elles le chausson s''ouvre au four','Base tomate en couche mince, pas en sauce : le calzone n''est pas une pizza pliée sur sa garniture liquide']::text[],
    ARRAY['pétrissage','fermentation','façonnage','pliage','cuisson au four']::text[], ARRAY['Au chorizo : six tranches ajoutées au jambon (750g)','Au bœuf haché : 200 g revenus avec un oignon, avec mozzarella et champignons (750g)','Ricotta, prosciutto, mozzarella et basilic frais, sans base tomate (chefsimon)','Tomate-mozzarella seule, quatre boules de mozzarella et du basilic frais, jaune d''œuf pour la dorure (marmiton)','Une cuillerée à café d''origan séché pétrie dans la pâte elle-même (chefsimon)']::text[], ARRAY['gluten','lait']::text[],
    'Se garde 3 jours au réfrigérateur, emballé, et se réchauffe 10 minutes à 200 °C sur une grille pour que le dessous redevienne croustillant — le micro-ondes le rend caoutchouteux. Les pâtons crus se congèlent 2 mois, huilés et emballés séparément : on les sort la veille au réfrigérateur et on les laisse revenir une heure à température ambiante avant de les étaler. Les calzones cuits se congèlent aussi 2 mois et se réchauffent sans décongélation, 20 minutes à 190 °C.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

