  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 10, 'g', 'required',
     'pâte', false, 10);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'origan seche' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Origan séché', 2, 'g', 'optional',
     'aromate', true, 11);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Délayer la levure sèche dans l''eau tiède et laisser reposer dix minutes, le temps qu''une mousse apparaisse en surface. Cette mousse est le seul test fiable : une levure morte ne fait rien voir et on ne s''en aperçoit qu''une heure plus tard devant une pâte plate.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Mélanger la farine et le sel dans un grand saladier, verser l''eau levurée puis l''huile d''olive, et pétrir dix minutes jusqu''à obtenir une pâte souple qui se décolle des doigts. Le sel doit rejoindre la farine et non l''eau : au contact direct de la levure il en tue une partie.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Couvrir d''un linge humide et laisser pousser une heure et demie à température ambiante, jusqu''au doublement du volume. Pendant ce temps, émincer les champignons et les faire suer à sec dans une poêle chaude jusqu''à ce qu''ils aient rendu et réabsorbé leur eau. Ce passage est obligatoire : des champignons crus rendent leur eau dans le chausson fermé et détrempent la pâte par l''intérieur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Diviser la pâte en quatre pâtons, les étaler au rouleau en disques de vingt-cinq centimètres, et étaler le concentré de tomate en couche mince sur une moitié seulement de chaque disque, en laissant deux centimètres de bord nus. Le bord sec est ce qui permettra la soudure ; une trace de sauce dessus et le chausson s''ouvre au four.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Répartir sur cette moitié la mozzarella égouttée et coupée en dés, le jambon en lanières, les champignons refroidis et l''emmental râpé, puis l''origan si l''on en met. La mozzarella doit être égouttée puis épongée : c''est la première source d''eau d''un calzone raté.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Rabattre la pâte nue sur la garniture, souder le bord en pressant à la fourchette ou en le roulant sur lui-même, et percer deux fentes courtes sur le dessus. Les fentes laissent sortir la vapeur ; sans elles la pâte gonfle en ballon et se déchire au point le plus faible, qui est toujours la soudure.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Badigeonner d''un peu d''huile d''olive et enfourner à 240 °C, chaleur tournante, quinze à vingt minutes, jusqu''à ce que la pâte soit dorée et ferme au toucher. Le four doit être à pleine température au moment de l''enfournement : un four qui monte encore laisse le dessous blanc et mou. Laisser reposer cinq minutes avant de couper, le temps que le fromage cesse de couler.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-005', 'recipe_family', 'Calzone',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-005', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au chorizo : six tranches ajoutées au jambon (750g)','Au bœuf haché : 200 g revenus avec un oignon, avec mozzarella et champignons (750g)','Ricotta, prosciutto, mozzarella et basilic frais, sans base tomate (chefsimon)','Tomate-mozzarella seule, quatre boules de mozzarella et du basilic frais, jaune d''œuf pour la dorure (marmiton)','Une cuillerée à café d''origan séché pétrie dans la pâte elle-même (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-005","variants":["Au chorizo : six tranches ajoutées au jambon (750g)","Au bœuf haché : 200 g revenus avec un oignon, avec mozzarella et champignons (750g)","Ricotta, prosciutto, mozzarella et basilic frais, sans base tomate (chefsimon)","Tomate-mozzarella seule, quatre boules de mozzarella et du basilic frais, jaune d''œuf pour la dorure (marmiton)","Une cuillerée à café d''origan séché pétrie dans la pâte elle-même (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-005', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('5c2ce6ca1a51c88b6e74d5516bf2e194'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["mozzarella fondue","tomate concentrée","jambon","pâte cuite"],"aroma_families":["lacté","tomate_cuite","pain grillé","champignon"],"target_textures":["croûte croustillante","intérieur_fondant_ou_crémeux","champignon_fondant"],"signature_ingredients":["Farine de blé T55","Mozzarella","Jambon blanc cuit"],"identity_guardrails":["C''est une pâte à pizza levée et refermée : une pâte brisée ou feuilletée en ferait un chausson, pas un calzone","La garniture doit être sèche — mozzarella égouttée, champignons précuits — sinon la vapeur détrempe la pâte de l''intérieur","Deux centimètres de bord nus pour souder, et deux fentes sur le dessus : sans elles le chausson s''ouvre au four","Base tomate en couche mince, pas en sauce : le calzone n''est pas une pizza pliée sur sa garniture liquide"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Pizza napolitaine', 'pizza napolitaine', 'Italie', 'Italie',
     'meal', 'pizza', 'named_traditional_dish', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Pizza napolitaine', 'Pizza à pâte fine garnie de tomate, d''anchois et d''oignon', ds.id, 'VAR-006',
    'Myko', 'editorial', 4, 20, 30, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '2cf432415e664db04466573bd9896b47',
    '{"sweet":3,"salty":4,"acidic":3,"bitter":1,"umami":5,"heat":0,"pungency":2,"richness":2,"freshness":1,"intensity":4}'::jsonb, ARRAY['anchois','oignon compoté','tomate cuite','thym']::text[],
    ARRAY['marin','oignon_compoté','tomate_cuite','thym']::text[], ARRAY['croûte alvéolée','légumes fondants','contraste_léger']::text[],
    ARRAY['Anchois à l''huile, égoutté','Oignon jaune cru','Tomate fraîche mûre']::text[], ARRAY['Aucune des deux sources retenues ne met de fromage : cette napolitaine-là n''en porte pas, et en ajouter en ferait une autre pizza','Les oignons se comptent en centaines de grammes et se compotent avant : crus, ils restent piquants et ne fondent pas en dix minutes de four','Les anchois entrent avant la cuisson pour que leur sel se diffuse dans la tomate','Tomates fraîches réduites à la poêle, jamais posées crues : elles noieraient la pâte']::text[],
    ARRAY['pétrissage','fermentation lente','compotage','réduction','cuisson haute température']::text[], ARRAY['Version italienne : coulis de tomate et mozzarella di bufala sur la même pâte, origan sec et basilic frais, sans oignon ni anchois (chefsimon)','Huile d''olive pimentée en finition à la place de l''huile d''olive nature (chefsimon)','Pâte laissée à fermenter 24 heures au froid, avec la même dose de levure (chefsimon)']::text[], ARRAY['gluten','poisson']::text[],
    'Se mange à la sortie du four. Les parts restantes se gardent 2 jours au réfrigérateur et se réchauffent 6 minutes à 220 °C sur une plaque chaude. La compotée d''oignons et la réduction de tomate se préparent 3 jours à l''avance et se gardent séparément au réfrigérateur — c''est ce qui ramène le plat à vingt minutes le soir venu. Les deux garnitures se congèlent 3 mois ; la pâte crue se congèle en pâtons 2 mois.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
