  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Mettre le lait à chauffer avec les bâtons de cannelle et le zeste de citron prélevé au couteau économe, sans la peau blanche. Porter à la limite du frémissement, couper le feu, couvrir et laisser infuser vingt minutes. Le blanc du citron est amer et l''amertume ressort après le refroidissement, quand il est trop tard pour la corriger.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Pendant ce temps, battre au fouet les jaunes d''œuf et le sucre : le mélange doit pâlir et retomber en ruban quand on soulève le fouet. Y incorporer alors la fécule de maïs en pluie. La fécule veut être délayée à froid dans une masse dense — jetée dans du lait chaud, elle prend en grumeaux instantanément et rien ne les défera.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Retirer la cannelle et le zeste, puis verser le lait chaud en filet sur les jaunes en fouettant sans arrêt. Verser lentement et sur le côté du fouet : le lait bouillant jeté d''un coup cuit les jaunes en filaments jaunes qu''on ne rattrape plus qu''au chinois.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Reverser le tout dans la casserole et cuire à feu moyen en remuant à la spatule en formant des huit au fond, jusqu''à ce que la crème épaississe nettement et laisse une trace au doigt sur le dos de la spatule. Cinq à huit minutes suffisent. Contrairement à la crème brûlée, celle-ci cuit sur le feu et non au four : c''est la fécule qui la tient, et elle a besoin d''atteindre l''ébullition légère pour agir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter la vanille liquide si l''on en met, puis verser aussitôt dans des ramequins plats et larges. La forme compte : un ramequin large donne une couche de crème mince et beaucoup de surface à caraméliser, ce qui est le rapport voulu entre le croquant et le crémeux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Laisser refroidir à température ambiante puis mettre au réfrigérateur quatre heures au moins, la nuit de préférence, à découvert la première heure puis filmé au contact. Un film posé sur une crème tiède retombe en eau condensée à la surface, et le caramel ne prendra jamais dessus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Au dernier moment, saupoudrer chaque ramequin d''une couche fine et régulière de cassonade et la brûler au chalumeau ou sous un gril brûlant, jusqu''à ce qu''elle fonde et brunisse. La couche doit être mince : trop épaisse, le sucre du dessous reste en grains et le caramel ne durcit pas. Servir dans les cinq minutes — le caramel ramollit au contact de la crème froide.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-012', 'recipe_family', 'Crème catalane',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-012', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
