  FROM axis
  CROSS JOIN unnest(ARRAY['À l''orange : zeste d''orange à la place du citron et 5 cl de liqueur d''orange (marmiton)','Au lait de coco : moitié lait, moitié lait de coco, noix de coco râpée sur le dessus (marmiton)','À la crème : 25 cl de crème liquide pour 10 cl de lait, avec des graines d''anis vert pilées (marmiton)','À la fleur d''oranger, deux cuillerées à café dans le lait infusé (chefsimon)','Version enrichie : deux œufs entiers en plus des quatre jaunes, et 20 g de farine avec la fécule (chefsimon)']::text[]) AS variant(name);

