  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-012', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('82fa7e2d483c69fed123990999441181'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"sweet_spiced","scores":{"sweet":5,"salty":0,"acidic":1,"bitter":1,"umami":1,"heat":0,"pungency":0,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["cannelle","citron","lait cuit","caramel"],"aroma_families":["cannelle","agrume","lacté","caramel"],"target_textures":["crémeux","caramel croquant","contraste_léger"],"signature_ingredients":["Lait entier","Jaune d''œuf cru","Bâton de cannelle"],"identity_guardrails":["Elle cuit sur le feu et se lie à la fécule : passée au four au bain-marie, ce serait une crème brûlée","Un jaune pour environ 165 ml de lait — deux fois moins riche qu''une crème brûlée, et c''est voulu","Cannelle et zeste de citron infusés dans le lait : ce sont les deux parfums qui la nomment","Le caramel se brûle au dernier moment ; posé d''avance, il fond dans la crème froide en un quart d''heure"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
