  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Tailler le poulet en lanières d''un centimètre dans le sens contraire des fibres et le mettre à mariner avec les deux tiers de l''huile d''olive, la moitié du jus de citron, la moitié de l''ail haché, le paprika, le cumin, l''origan, du sel et du poivre. Deux heures au frais, quatre si l''on peut. Le citron attendrit et parfume, mais au-delà d''une nuit il cuit la surface de la viande et la rend cotonneuse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Égoutter le yaourt nature une heure dans une passoire garnie d''un linge, au réfrigérateur. C''est ce qui lui donne la consistance d''un yaourt à la grecque, que trois des sources emploient et que le catalogue ne porte pas : sans cet égouttage la sauce coule du pain avant qu''on ait mordu dedans.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Râper le concombre à la grosse grille, le saler légèrement, le laisser dégorger vingt minutes puis le presser fort entre les mains. Un concombre non pressé rend deux à trois cuillerées d''eau dans la sauce en une demi-heure. Le mêler au yaourt égoutté avec le reste d''ail et de jus de citron, saler, poivrer, et réserver au froid.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Émincer le poivron en lanières et le faire sauter à feu vif cinq à six minutes dans une poêle très chaude, jusqu''à ce qu''il marque par endroits mais reste ferme. Ajouté cru au sandwich il reste aqueux et fade ; longuement cuit il s''affaisse et détrempe le pain.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Saisir les lanières de poulet dans la même poêle brûlante, en deux fois pour ne pas la charger, quatre à cinq minutes en tout, jusqu''à ce qu''elles soient dorées sur les arêtes. Une poêle chargée fait tomber la température et la viande rend son eau puis bout : elle blanchit au lieu de colorer, et le gyros perd ce qui le caractérise, ces bords grillés.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Réchauffer les pitas trente secondes par face dans la poêle vide, le temps qu''ils gonflent et redeviennent souples. Un pita froid casse quand on le plie, un pita trop chauffé sèche et s''effrite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Garnir chaque pita d''une couche de sauce au yaourt, puis de laitue ciselée, de poulet, de poivrons, de tomate en dés et d''oignon rouge en fines lamelles, et terminer d''une seconde cuillerée de sauce. La sauce se met en premier et en dernier : la première couche fait barrière entre le pain et le jus des légumes, la seconde tient l''ensemble. Rouler serré et manger aussitôt.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-013', 'recipe_family', 'Gyros de poulet',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-013', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Gyros de porc : un rôti de 800 g braisé une heure dans une sauce tomate au cumin, au piment et à l''origan, servi avec trois couleurs de poivron (marmiton)','Au tzatziki du commerce, 250 g pour quatre, à la place de la sauce au yaourt maison (chefsimon, 750g)','Avec 100 g de beaufort râpé dans le pita (chefsimon)','Version végétarienne : aubergines panées à la chapelure et au parmesan, roquette et tzatziki dans un wrap (chefsimon)','Mélange d''épices à gyros maison : ail en poudre, paprika, herbes de Provence, coriandre, cumin, poivre, sel, céleri en poudre et graines de moutarde à parts décroissantes (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-013","variants":["Gyros de porc : un rôti de 800 g braisé une heure dans une sauce tomate au cumin, au piment et à l''origan, servi avec trois couleurs de poivron (marmiton)","Au tzatziki du commerce, 250 g pour quatre, à la place de la sauce au yaourt maison (chefsimon, 750g)","Avec 100 g de beaufort râpé dans le pita (chefsimon)","Version végétarienne : aubergines panées à la chapelure et au parmesan, roquette et tzatziki dans un wrap (chefsimon)","Mélange d''épices à gyros maison : ail en poudre, paprika, herbes de Provence, coriandre, cumin, poivre, sel, céleri en poudre et graines de moutarde à parts décroissantes (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-013', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('dd2e3450a12deb11f1dcda0dddf861ec'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":1,"pungency":3,"richness":3,"freshness":3,"intensity":4},"dominant_flavors":["poulet grillé","yaourt à l''ail","citron","paprika"],"aroma_families":["origan","cumin","ail","agrume"],"target_textures":["pain moelleux","viande grillée","contraste_léger"],"signature_ingredients":["Blanc de poulet cru, sans peau","Pain pita","Yaourt nature"],"identity_guardrails":["Le poulet est saisi en deux fois dans une poêle brûlante : entassé, il bout et perd les arêtes grillées qui font le gyros","Le yaourt s''égoutte une heure — non égoutté, la sauce traverse le pain","Le concombre se dégorge et se presse, sinon il liquéfie la sauce en une demi-heure","Sauce en dessous et au-dessus de la garniture : la couche du bas protège le pain du jus des légumes"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Pastitsio', 'pastitsio', 'Grèce', 'Grèce',
     'meal', 'pâtes au four', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Pastitsio', 'Pâtes courtes et bœuf haché à la tomate, recouverts de béchamel et gratinés au four', ds.id, 'VAR-014',
    'Myko', 'editorial', 6, 45, 60, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'b17ea44f827bac7123d1d8daec5ade23',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":0,"intensity":4}'::jsonb, ARRAY['cannelle','bœuf','tomate mijotée','béchamel']::text[],
    ARRAY['cannelle','bœuf','tomate_cuite','lacté']::text[], ARRAY['croûte gratinée','pâtes_fermes','sauce_épaisse']::text[],
    ARRAY['Bœuf haché cru','Pâtes sèches courtes','Cannelle moulue']::text[], ARRAY['La cannelle dans la viande fait le pastitsio ; sans elle c''est un gratin de pâtes à la bolognaise','La béchamel est liée aux œufs — c''est elle qui prend en flan et permet de trancher des parts nettes','Les pâtes se cuisent trois minutes en moins : elles terminent au four','Un quart d''heure de repos avant la découpe, sinon le plat s''affaisse dans l''assiette']::text[],
    ARRAY['mijotage','cuisson al dente','béchamel','liaison aux œufs','montage','gratinage','repos']::text[], ARRAY['Aux bucatini plutôt qu''aux macaronis, avec un verre de vin rouge, une carotte en petits dés, trois feuilles de laurier et de l''origan dans la viande (chefsimon)','Au pecorino ou à un fromage râpé grec à la place du gruyère, moitié dans les pâtes, moitié dans la béchamel (chefsimon)','Viande de bœuf, porc et agneau mélangés à parts égales (chefsimon)','Sauce montée au bouillon de légumes, 35 cl, à la place d''une partie de la tomate (750g)','Deux oignons rouges et une gousse d''ail entière retirée avant montage, avec des grains de coriandre écrasés (marmiton)']::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se garde 4 jours au réfrigérateur et se réchauffe par parts, 15 minutes à 180 °C, en couvrant d''aluminium les dix premières minutes. Il se coupe d''ailleurs mieux froid que chaud. Se congèle 3 mois, cru et monté ou déjà cuit : cru, il s''enfourne sans décongélation en ajoutant vingt-cinq minutes ; cuit, il se réchauffe une nuit de décongélation puis 25 minutes au four. C''est l''un des plats du lot qui gagne le plus à être fait en double.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
