  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux bucatini plutôt qu''aux macaronis, avec un verre de vin rouge, une carotte en petits dés, trois feuilles de laurier et de l''origan dans la viande (chefsimon)','Au pecorino ou à un fromage râpé grec à la place du gruyère, moitié dans les pâtes, moitié dans la béchamel (chefsimon)','Viande de bœuf, porc et agneau mélangés à parts égales (chefsimon)','Sauce montée au bouillon de légumes, 35 cl, à la place d''une partie de la tomate (750g)','Deux oignons rouges et une gousse d''ail entière retirée avant montage, avec des grains de coriandre écrasés (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-014","variants":["Aux bucatini plutôt qu''aux macaronis, avec un verre de vin rouge, une carotte en petits dés, trois feuilles de laurier et de l''origan dans la viande (chefsimon)","Au pecorino ou à un fromage râpé grec à la place du gruyère, moitié dans les pâtes, moitié dans la béchamel (chefsimon)","Viande de bœuf, porc et agneau mélangés à parts égales (chefsimon)","Sauce montée au bouillon de légumes, 35 cl, à la place d''une partie de la tomate (750g)","Deux oignons rouges et une gousse d''ail entière retirée avant montage, avec des grains de coriandre écrasés (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-014', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b17ea44f827bac7123d1d8daec5ade23'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":0,"intensity":4},"dominant_flavors":["cannelle","bœuf","tomate mijotée","béchamel"],"aroma_families":["cannelle","bœuf","tomate_cuite","lacté"],"target_textures":["croûte gratinée","pâtes_fermes","sauce_épaisse"],"signature_ingredients":["Bœuf haché cru","Pâtes sèches courtes","Cannelle moulue"],"identity_guardrails":["La cannelle dans la viande fait le pastitsio ; sans elle c''est un gratin de pâtes à la bolognaise","La béchamel est liée aux œufs — c''est elle qui prend en flan et permet de trancher des parts nettes","Les pâtes se cuisent trois minutes en moins : elles terminent au four","Un quart d''heure de repos avant la découpe, sinon le plat s''affaisse dans l''assiette"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Chich taouk', 'chich taouk', 'Levant', 'Levant',
     'meal', 'brochette', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Chich taouk', 'Brochettes de blanc de poulet marinées à l''ail, au thym et à la cannelle, grillées', ds.id, 'VAR-016',
    'Myko', 'editorial', 4, 15, 15, 'facile',
    NULL, NULL,
    'B', 'candidate', '78828b4416b89adfbaf82b9d4b45bae3',
    '{"sweet":1,"salty":3,"acidic":4,"bitter":0,"umami":2,"heat":2,"pungency":4,"richness":2,"freshness":3,"intensity":4}'::jsonb, ARRAY['ail','citron','cannelle','poulet grillé']::text[],
    ARRAY['ail','agrume','cannelle','safran']::text[], ARRAY['chair_moelleuse','arêtes grillées','tendre']::text[],
    ARRAY['Blanc de poulet cru, sans peau','Ail cru','Cannelle moulue']::text[], ARRAY['L''ail se compte en grammes, pas en pincées : vingt grammes pour quatre, écrasés en pâte','La cannelle et le safran font l''identité levantine du plat — sans elles ce sont des brochettes citron-ail','Le safran s''infuse à l''eau chaude avant d''entrer dans la marinade, il ne se diffuse pas dans l''huile','Pas plus de douze heures de marinade : l''acide du citron finit par rendre la chair farineuse']::text[],
    ARRAY['marinade','infusion du safran','embrochage','grillade']::text[], ARRAY['Marinade au yaourt : un yaourt bulgare, dix gousses d''ail, un citron, une cuillerée de paprika et une de thym séché (chefsimon)','Une cuillerée à café de sumac dans la marinade, ou saupoudré au service (marmiton, chefsimon)','Une cuillerée à café de cumin en plus de la cannelle (marmiton)','Version simplifiée au concentré de tomates, ail, citron et huile d''olive, sans épices (marmiton)']::text[], ARRAY[]::text[],
    'Le poulet mariné cru se garde 24 heures au réfrigérateur et se congèle 2 mois dans sa marinade, ce qui en fait un des plats les plus rapides du lot une fois sorti la veille. Cuit, il se garde 3 jours au réfrigérateur et se mange froid en salade ou dans un pain plat ; réchauffé, il sèche. Ne pas recongeler après cuisson.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'blanc de poulet cru sans peau' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Blanc de poulet cru, sans peau', 600, 'g', 'required',
     'protéine', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'citron jaune frais' AND ff.status <> 'rejected'
