  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Couper les blancs de poulet en cubes réguliers de trois centimètres. Plus petits, ils sèchent avant d''avoir coloré ; plus gros, l''extérieur brûle avant que le centre soit cuit. La régularité compte davantage que la taille exacte : des morceaux inégaux sur la même brochette ne seront jamais cuits ensemble.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Écraser l''ail en pâte avec le sel — au mortier ou à plat sur la planche, avec le côté du couteau. L''ail en pâte enrobe la viande, l''ail haché reste en morceaux qui brûlent sur le gril et donnent de l''amertume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire tremper le safran dans une cuillerée à soupe d''eau chaude dix minutes, le temps qu''il donne sa couleur. Jeté sec dans une marinade huileuse, il ne se diffuse pas : le safran est soluble dans l''eau, pas dans l''huile, et c''est pourquoi cette étape n''est pas une coquetterie.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Mélanger l''huile d''olive, le jus des citrons, l''ail en pâte, le thym, la cannelle, le piment et l''infusion de safran, y rouler les cubes de poulet et laisser mariner au réfrigérateur deux heures au minimum, une nuit de préférence. Ne pas dépasser douze heures : au-delà, l''acide du citron dénature la surface de la viande et la rend farineuse à la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Enfiler les morceaux sur des brochettes sans les tasser, en laissant un demi-centimètre entre chaque. Serrés, ils cuisent à la vapeur les uns contre les autres et ressortent blancs et mous ; espacés, la chaleur circule et chaque face colore.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Cuire sur un gril très chaud, au barbecue ou sur une plaque en fonte, six à huit minutes en tournant les brochettes tous les deux tiers de tour. Le poulet est cuit dès que le jus qui perle est clair — au-delà de deux minutes de plus, le blanc devient sec et rien ne le rattrape. Laisser reposer deux minutes avant de servir, avec le reste de citron en quartiers.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-016', 'recipe_family', 'Chich taouk',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-016', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Marinade au yaourt : un yaourt bulgare, dix gousses d''ail, un citron, une cuillerée de paprika et une de thym séché (chefsimon)','Une cuillerée à café de sumac dans la marinade, ou saupoudré au service (marmiton, chefsimon)','Une cuillerée à café de cumin en plus de la cannelle (marmiton)','Version simplifiée au concentré de tomates, ail, citron et huile d''olive, sans épices (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-016","variants":["Marinade au yaourt : un yaourt bulgare, dix gousses d''ail, un citron, une cuillerée de paprika et une de thym séché (chefsimon)","Une cuillerée à café de sumac dans la marinade, ou saupoudré au service (marmiton, chefsimon)","Une cuillerée à café de cumin en plus de la cannelle (marmiton)","Version simplifiée au concentré de tomates, ail, citron et huile d''olive, sans épices (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-016', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('78828b4416b89adfbaf82b9d4b45bae3'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":4,"bitter":0,"umami":2,"heat":2,"pungency":4,"richness":2,"freshness":3,"intensity":4},"dominant_flavors":["ail","citron","cannelle","poulet grillé"],"aroma_families":["ail","agrume","cannelle","safran"],"target_textures":["chair_moelleuse","arêtes grillées","tendre"],"signature_ingredients":["Blanc de poulet cru, sans peau","Ail cru","Cannelle moulue"],"identity_guardrails":["L''ail se compte en grammes, pas en pincées : vingt grammes pour quatre, écrasés en pâte","La cannelle et le safran font l''identité levantine du plat — sans elles ce sont des brochettes citron-ail","Le safran s''infuse à l''eau chaude avant d''entrer dans la marinade, il ne se diffuse pas dans l''huile","Pas plus de douze heures de marinade : l''acide du citron finit par rendre la chair farineuse"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Labneh', 'labneh', 'Levant', 'Levant',
     'meal', 'condiment', 'named_traditional_dish', 'tangy_creamy',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Labneh', 'Yaourt égoutté jusqu''à consistance de fromage frais, servi à l''huile d''olive et à la menthe', ds.id, 'VAR-017',
    'Myko', 'editorial', 6, 15, 0, 'facile',
    NULL, NULL,
    'B', 'candidate', '9dec6a3dc7935ad7a257f9136ebbd493',
    '{"sweet":1,"salty":3,"acidic":4,"bitter":0,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":2}'::jsonb, ARRAY['yaourt acidulé','huile d''olive','menthe']::text[],
    ARRAY['lacté','herbacé','huile_olive']::text[], ARRAY['crémeux','onctueux et dense']::text[],
    ARRAY['Yaourt nature','Huile d''olive vierge extra','Menthe fraîche']::text[], ARRAY['Le sel entre avant l''égouttage et non après : c''est lui qui fait sortir le petit-lait','Le temps d''égouttage est le seul réglage — douze heures pour tartiner, vingt-quatre pour rouler en boules','Le petit-lait ne doit jamais retremper le fond de la passoire, sinon l''égouttage s''arrête','Ce n''est pas un yaourt assaisonné : sans les douze heures d''égouttage, il n''y a pas de labneh']::text[],
    ARRAY['salage','égouttage','repos au froid']::text[], ARRAY['Au zaatar, une à deux cuillerées à café saupoudrées sur l''huile (marmiton, chefsimon)','Citronné : jus et zeste d''un citron mêlés au labneh, sumac, olives noires et amandes effilées grillées (chefsimon)','À l''ail : de l''ail en semoule mêlé au yaourt avant égouttage, menthe et paprika (marmiton)','Roulé en boules et conservé sous huile d''olive dans un bocal, après vingt-quatre heures d''égouttage','À base de fromage blanc battu épais plutôt que de yaourt, sans égouttage (marmiton)']::text[], ARRAY['lait']::text[],
    'Se garde 5 jours au réfrigérateur en récipient fermé, sans son huile, qu''on verse au moment de servir. Roulé en boules et couvert d''huile d''olive dans un bocal, il se garde 3 semaines au réfrigérateur — c''est la conservation traditionnelle. Ne se congèle pas : le gel se rompt et la pâte ressort granuleuse et pleine d''eau. Le petit-lait recueilli se garde 3 jours et remplace une partie du liquide d''une pâte à pain ou d''une soupe froide.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'yaourt nature' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Yaourt nature', 560, 'g', 'required',
     'base', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'huile d olive vierge extra' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Huile d''olive vierge extra', 40, 'ml', 'required',
     'finition', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'menthe fraiche' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Menthe fraîche', 8, 'g', 'required',
     'herbe', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'paprika doux' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Paprika doux', 1, 'g', 'required',
     'finition', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 4, 'g', 'required',
     'égouttage', false, 5);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Mélanger le yaourt et le sel dans un saladier, à la cuillère, jusqu''à ce que le sel ait entièrement disparu. Le sel n''est pas ici un assaisonnement mais l''agent de l''opération : il rompt le gel du yaourt et fait sortir le petit-lait. Un yaourt non salé s''égoutte deux fois plus lentement et rend une pâte granuleuse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Tapisser une passoire d''un linge fin propre ou d''une double épaisseur de gaze, y verser le yaourt salé, rabattre les coins du linge par-dessus, et poser la passoire sur un saladier assez profond pour que le fond ne trempe jamais dans le petit-lait qui s''écoule.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Laisser égoutter au réfrigérateur douze heures pour une texture de fromage à tartiner, vingt-quatre pour une pâte assez ferme pour être roulée en boules. C''est le seul réglage du plat : le temps décide de la texture, et rien d''autre. Vider le petit-lait une fois en cours de route.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Récupérer le labneh dans le linge, le lisser à la cuillère et le goûter. Il doit être franchement acidulé et légèrement salé ; s''il paraît fade, c''est que le yaourt de départ l''était, et une pincée de sel ajoutée maintenant ne rattrape que la moitié du chemin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Étaler le labneh en couche épaisse dans une assiette creuse, creuser un sillon au dos de la cuillère, y verser l''huile d''olive et parsemer de menthe ciselée et de paprika. Le sillon n''est pas décoratif : il retient l''huile au centre au lieu de la laisser filer sur les bords de l''assiette.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-017', 'recipe_family', 'Labneh',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-017', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au zaatar, une à deux cuillerées à café saupoudrées sur l''huile (marmiton, chefsimon)','Citronné : jus et zeste d''un citron mêlés au labneh, sumac, olives noires et amandes effilées grillées (chefsimon)','À l''ail : de l''ail en semoule mêlé au yaourt avant égouttage, menthe et paprika (marmiton)','Roulé en boules et conservé sous huile d''olive dans un bocal, après vingt-quatre heures d''égouttage','À base de fromage blanc battu épais plutôt que de yaourt, sans égouttage (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-017","variants":["Au zaatar, une à deux cuillerées à café saupoudrées sur l''huile (marmiton, chefsimon)","Citronné : jus et zeste d''un citron mêlés au labneh, sumac, olives noires et amandes effilées grillées (chefsimon)","À l''ail : de l''ail en semoule mêlé au yaourt avant égouttage, menthe et paprika (marmiton)","Roulé en boules et conservé sous huile d''olive dans un bocal, après vingt-quatre heures d''égouttage","À base de fromage blanc battu épais plutôt que de yaourt, sans égouttage (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-017', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('9dec6a3dc7935ad7a257f9136ebbd493'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"tangy_creamy","scores":{"sweet":1,"salty":3,"acidic":4,"bitter":0,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":2},"dominant_flavors":["yaourt acidulé","huile d''olive","menthe"],"aroma_families":["lacté","herbacé","huile_olive"],"target_textures":["crémeux","onctueux et dense"],"signature_ingredients":["Yaourt nature","Huile d''olive vierge extra","Menthe fraîche"],"identity_guardrails":["Le sel entre avant l''égouttage et non après : c''est lui qui fait sortir le petit-lait","Le temps d''égouttage est le seul réglage — douze heures pour tartiner, vingt-quatre pour rouler en boules","Le petit-lait ne doit jamais retremper le fond de la passoire, sinon l''égouttage s''arrête","Ce n''est pas un yaourt assaisonné : sans les douze heures d''égouttage, il n''y a pas de labneh"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Tajine de kefta', 'tajine de kefta', 'Maroc', 'Maroc',
     'meal', 'plat mijoté', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Tajine de kefta', 'Boulettes de bœuf haché mijotées dans une sauce tomate aux olives vertes et à la coriandre', ds.id, 'VAR-018',
    'Myko', 'editorial', 4, 20, 30, 'facile',
    NULL, NULL,
    'B', 'candidate', 'b33730e1878e4a0f3570b13be1aa15b3',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":1,"pungency":3,"richness":3,"freshness":2,"intensity":4}'::jsonb, ARRAY['cumin','coriandre fraîche','tomate mijotée','bœuf']::text[],
    ARRAY['cumin','coriandre','tomate_cuite','paprika']::text[], ARRAY['farce moelleuse','sauce_nappante','jaune d''œuf coulant']::text[],
    ARRAY['Bœuf haché cru','Cumin moulu','Coriandre fraîche']::text[], ARRAY['Cumin et coriandre fraîche ensemble : ce sont les deux marqueurs du plat, présents dans six et huit pages sur neuf','L''oignon de la farce se râpe et ne se hache pas — en morceaux, il fait éclater les boulettes','Les œufs se cassent dans la sauce déjà réduite et cuisent à couvert cinq à sept minutes : le jaune reste coulant','On ne remue pas les boulettes à la cuillère, on secoue le plat']::text[],
    ARRAY['hachage','façonnage','mijotage','réduction','pochage des œufs']::text[], ARRAY['Aux pommes de terre : 600 g en quartiers ajoutés à la sauce et mijotés une heure, sans œufs (chefsimon, 750g)','Aux petits pois : 500 g ajoutés en fin de cuisson avec six œufs pour trois personnes (marmiton)','Aux patates douces et haricots rouges : trois patates douces, une boîte de haricots rouges et deux courgettes, une heure et demie de cuisson (marmiton)','Épicée au ras el-hanout, une à deux cuillerées à café en plus du cumin et du paprika (chefsimon, 750g)','À la cannelle : une demi-cuillerée à soupe mêlée au cumin dans la farce des boulettes (chefsimon)','Aux poivrons grillés : deux poivrons pelés et taillés en lanières ajoutés à la sauce (chefsimon)']::text[], ARRAY['œuf']::text[],
    'Se garde 3 jours au réfrigérateur, mais sans les œufs, qu''on ajoute au réchauffage : un jaune cuit deux fois devient sableux. Les boulettes crues se gardent 24 heures et se congèlent 3 mois, crues et espacées sur une plaque avant d''être mises en sac — elles cuisent alors sans décongélation en ajoutant cinq minutes de mijotage. La sauce seule se congèle 3 mois. Réchauffer à couvert et à feu doux avec une cuillerée d''eau.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

