  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-018', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b33730e1878e4a0f3570b13be1aa15b3'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":1,"pungency":3,"richness":3,"freshness":2,"intensity":4},"dominant_flavors":["cumin","coriandre fraîche","tomate mijotée","bœuf"],"aroma_families":["cumin","coriandre","tomate_cuite","paprika"],"target_textures":["farce moelleuse","sauce_nappante","jaune d''œuf coulant"],"signature_ingredients":["Bœuf haché cru","Cumin moulu","Coriandre fraîche"],"identity_guardrails":["Cumin et coriandre fraîche ensemble : ce sont les deux marqueurs du plat, présents dans six et huit pages sur neuf","L''oignon de la farce se râpe et ne se hache pas — en morceaux, il fait éclater les boulettes","Les œufs se cassent dans la sauce déjà réduite et cuisent à couvert cinq à sept minutes : le jaune reste coulant","On ne remue pas les boulettes à la cuillère, on secoue le plat"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Tajine de légumes', 'tajine de legumes', 'Maroc', 'Maroc',
     'meal', 'légume mijoté', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Tajine de légumes', 'Pommes de terre, courgettes, carottes et navets mijotés ensemble à la tomate', ds.id, 'VAR-019',
    'Myko', 'editorial', 6, 20, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '09f482e2ee3953d225bc5c290ea762dc',
    '{"sweet":3,"salty":2,"acidic":2,"bitter":1,"umami":2,"heat":0,"pungency":3,"richness":2,"freshness":2,"intensity":3}'::jsonb, ARRAY['cumin','curcuma','légumes fondants','coriandre fraîche']::text[],
    ARRAY['cumin','épices chaudes','végétal cuit','coriandre']::text[], ARRAY['légumes fondants','jus court et nappant','morceaux entiers']::text[],
    ARRAY['Pomme de terre crue, épluchée','Cumin moulu','Curcuma moulu']::text[], ARRAY['Aucune viande et aucun poisson : trois pages du dossier en portent sous ce titre, et c''est exactement ce que cette recette n''est pas','Les épices s''ouvrent dans l''huile avant les légumes, sinon elles restent en poudre','Morceaux gros et montage en dôme, les longs à cuire au fond : c''est ce qui permet de tout cuire ensemble','On ne remue jamais : un tajine remué devient une ratatouille']::text[],
    ARRAY['suer','épices ouvertes dans le gras','cuisson à l''étouffée','montage en dôme','repos']::text[], ARRAY['Aux olives, 80 g égouttées ajoutées dans les dix dernières minutes (marmiton)','Aux pois chiches et fruits secs : 250 g de pois chiches, 100 g d''abricots secs et 100 g de raisins secs, sur un lit de quinoa (marmiton)','Aux haricots verts et petits pois : 250 g de chaque, ajoutés à mi-cuisson, avec deux aubergines et deux branches de céleri (750g)','Au ras el-hanout, une cuillerée à café en plus des épices moulues (marmiton, 750g)','Au safran : une pincée infusée dans le bouillon, avec un piment fort entier (chefsimon)']::text[], ARRAY[]::text[],
    'Se garde 4 jours au réfrigérateur et se réchauffe à couvert, à feu doux, avec deux cuillerées d''eau. Il gagne au réchauffage, les épices continuant de diffuser. Se congèle 3 mois, mais en retirant les pommes de terre, qui ressortent granuleuses — les courgettes, elles, s''affaissent sans nuire au plat. C''est un bon candidat au double : la moitié se sert en plat, l''autre se mixe en soupe épaisse ou se glisse dans une semoule.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
